eading -->\n<h2>Key features of the Love Nature template</h2>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Well-designed multipurpose template</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Elegant and serene design</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Natural color palette with customization options</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Professional and flexible layout</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Compatible with popular page builders</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\";s:12:\"post-excerpt\";s:67:\"Elegant and serene multipurpose design to build any type of website\";s:5:\"pages\";a:4:{s:8:\"id-88224\";a:12:{s:5:\"title\";s:4:\"Home\";s:18:\"featured-image-url\";s:70:\"https://websitedemos.net/wp-content/uploads/2021/11/love-nature-02.jpg\";s:19:\"thumbnail-image-url\";s:79:\"https://websitedemos.net/wp-content/uploads/2021/11/love-nature-02-600x1449.jpg\";s:18:\"astra-page-api-url\";s:62:\"https://websitedemos.net/love-nature-02/wp-json/wp/v2/pages/11\";s:12:\"dynamic-page\";s:2:\"no\";s:14:\"astra-page-url\";s:34:\"//websitedemos.net/love-nature-02/\";s:15:\"astra-sites-tag\";a:1:{i:423;s:4:\"home\";}s:15:\"site-pages-type\";s:4:\"free\";s:23:\"site-pages-page-builder\";s:9:\"elementor\";s:19:\"site-pages-category\";a:0:{}s:26:\"site-pages-parent-category\";a:2:{i:60;s:8:\"business\";i:61;s:4:\"free\";}s:16:\"required-plugins\";a:1:{i:0;a:3:{s:4:\"slug\";s:9:\"elementor\";s:4:\"init\";s:23:\"elementor/elementor.php\";s:4:\"name\";s:9:\"Elementor\";}}}s:8:\"id-88225\";a:12:{s:5:\"title\";s:8:\"Services\";s:18:\"featured-image-url\";s:79:\"https://websitedemos.net/wp-content/uploads/2021/11/love-nature-02-services.jpg\";s:19:\"thumbnail-image-url\";s:88:\"https://websitedemos.net/wp-content/uploads/2021/11/love-nature-02-services-600x1273.jpg\";s:18:\"astra-page-api-url\";s:62:\"https://websitedemos.net/love-nature-02/wp-json/wp/v2/pa