ocommerce/woocommerce.php\";s:4:\"name\";s:11:\"WooCommerce\";}}s:11:\"post-status\";s:7:\"publish\";s:12:\"post-content\";s:1194:\"<!-- wp:paragraph -->\n<p>The Planet Earth Store template is an eCommerce store design that uses graphics and calm colors to create a buying mood. Itâ€™s light, well-balanced and provides lots of opportunities to let your products stand out.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>The main page opens with a graphical banner you can use to set the scene before opening up into your product selection. Everything is customizable, everything is designed for speed and ease of use and could be used for any type of store.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2>Key features of the Planet Earth Store</h2>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Light and welcoming eCommerce store template</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Uses graphics and calm colors to draw you in</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Lots of options to build a profitable store</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Works flawlessly with SureCart and WooCommerce</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Full compatibility with leading page builders</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\";s:12:\"post-excerpt\";s:81:\"The Planet Earth Store template is a light store design thatâ€™s very easy to use\";s:5:\"pages\";a:0:{}s:19:\"related-bb-template\";s:0:\"\";s:26:\"related-elementor-template\";i:71669;s:26:\"related-gutenberg-template\";s:0:\"\";s:26:\"related_ecommerce_template\";s:0:\"\";s:25:\"ecommerce_parent_template\";s:0:\"\";}s:8:\"id-72580\";a:24:{s:5:\"title\";s:16:\"SaaS App Company\";s:2:\"id\";i:72580;s:12:\"publish-date\";i:1679478944;s:18:\"featured-image-url\";s:75:\"https://websitedemos.net/wp-content/uploads/2023/03/saas-app-company-04.jpg\";s:19:\"thumbnail-image-url\";s:84:\"https://websitedemos.ne