res of the Tanz Tech template</h2>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Youthful design ideal for many types of business</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Light, welcoming colors and typography</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Attractive page features that can be customized with ease</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Essential supplementary pages already built</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Full compatibility with leading page builders</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\";s:12:\"post-excerpt\";s:85:\"The Tanz Tech template is welcoming, well-designed and ideal for any type of business\";s:5:\"pages\";a:5:{s:8:\"id-72604\";a:12:{s:5:\"title\";s:4:\"Home\";s:18:\"featured-image-url\";s:63:\"https://websitedemos.net/wp-content/uploads/2023/03/saas-04.jpg\";s:19:\"thumbnail-image-url\";s:72:\"https://websitedemos.net/wp-content/uploads/2023/03/saas-04-600x3437.jpg\";s:18:\"astra-page-api-url\";s:54:\"https://websitedemos.net/saas-04/wp-json/wp/v2/pages/7\";s:12:\"dynamic-page\";s:2:\"no\";s:14:\"astra-page-url\";s:27:\"//websitedemos.net/saas-04/\";s:15:\"astra-sites-tag\";a:1:{i:423;s:4:\"home\";}s:15:\"site-pages-type\";s:11:\"agency-mini\";s:23:\"site-pages-page-builder\";s:9:\"elementor\";s:19:\"site-pages-category\";a:0:{}s:26:\"site-pages-parent-category\";a:1:{i:60;s:8:\"business\";}s:16:\"required-plugins\";a:3:{i:0;a:3:{s:4:\"slug\";s:9:\"elementor\";s:4:\"init\";s:23:\"elementor/elementor.php\";s:4:\"name\";s:9:\"Elementor\";}i:1;a:3:{s:4:\"slug\";s:23:\"header-footer-elementor\";s:4:\"init\";s:51:\"header-footer-elementor/header-footer-elementor.php\";s:4:\"name\";s:33:\"Elementor Header & Footer Builder\";}i:2;a:3:{s:4:\"slug\";s:18:\"ultimate-elementor\";s:4:\"init\";s:41:\"ultimate-elementor/ultimate-elementor.php\";s:4:\"name\";s:29:\"Ultimate Addons for Elementor\";}}}s:8:\"id-72601\";a:12:{s:5:\"t