 contact page so you have everything you need.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2>Key features of the Fiona Patisserie template</h2>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Light and relaxed WordPress food template</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Parallax effects and image blocks add character</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Option to add more content, images or store elements</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Attractive menu and contact pages</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Full compatibility with leading page builders</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\";s:12:\"post-excerpt\";s:71:\"Light hearted WordPress food template designed to help promote and sell\";s:5:\"pages\";a:4:{s:8:\"id-69843\";a:12:{s:5:\"title\";s:8:\"About Us\";s:18:\"featured-image-url\";s:84:\"https://websitedemos.net/wp-content/uploads/2022/11/fiona-patisserie-04-about-us.jpg\";s:19:\"thumbnail-image-url\";s:93:\"https://websitedemos.net/wp-content/uploads/2022/11/fiona-patisserie-04-about-us-600x2596.jpg\";s:18:\"astra-page-api-url\";s:67:\"https://websitedemos.net/fiona-patisserie-04/wp-json/wp/v2/pages/10\";s:12:\"dynamic-page\";s:2:\"no\";s:14:\"astra-page-url\";s:48:\"//websitedemos.net/fiona-patisserie-04/about-us/\";s:15:\"astra-sites-tag\";a:1:{i:455;s:8:\"about-us\";}s:15:\"site-pages-type\";s:11:\"agency-mini\";s:23:\"site-pages-page-builder\";s:9:\"elementor\";s:19:\"site-pages-category\";a:0:{}s:26:\"site-pages-parent-category\";a:1:{i:139;s:5:\"other\";}s:16:\"required-plugins\";a:3:{i:0;a:3:{s:4:\"slug\";s:9:\"elementor\";s:4:\"init\";s:23:\"elementor/elementor.php\";s:4:\"name\";s:9:\"Elementor\";}i:1;a:3:{s:4:\"slug\";s:18:\"ultimate-elementor\";s:4:\"init\";s:41:\"ultimate-elementor/ultimate-elementor.php\";s:4:\"name\";s:29:\"Ultimate Addons for Elementor\";}i:2;a:3:{s:4:\"slug\";s:12:\"wpforms-lite\";