2>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Clean and simple design that comes with everything you need to build a coaching business</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Seamlessly integrates with popular WordPress LMS plugins</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Create courses from scratch and manage them easily through your dashboard</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Customize just about everything</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Gutenberg and page builder ready</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\";s:12:\"post-excerpt\";s:80:\"Perfect solution for people who want to start an online health coaching business\";s:5:\"pages\";a:4:{s:8:\"id-47733\";a:12:{s:5:\"title\";s:4:\"Home\";s:18:\"featured-image-url\";s:83:\"https://websitedemos.net/wp-content/uploads/2020/10/online-health-coach-02-home.jpg\";s:19:\"thumbnail-image-url\";s:83:\"https://websitedemos.net/wp-content/uploads/2020/10/online-health-coach-02-home.jpg\";s:18:\"astra-page-api-url\";s:69:\"https://websitedemos.net/online-health-coach-02/wp-json/wp/v2/pages/7\";s:12:\"dynamic-page\";s:2:\"no\";s:14:\"astra-page-url\";s:42:\"//websitedemos.net/online-health-coach-02/\";s:15:\"astra-sites-tag\";a:1:{i:423;s:4:\"home\";}s:15:\"site-pages-type\";s:4:\"free\";s:23:\"site-pages-page-builder\";s:9:\"elementor\";s:19:\"site-pages-category\";a:0:{}s:26:\"site-pages-parent-category\";a:2:{i:60;s:8:\"business\";i:61;s:4:\"free\";}s:16:\"required-plugins\";a:1:{i:0;a:3:{s:4:\"slug\";s:9:\"elementor\";s:4:\"init\";s:23:\"elementor/elementor.php\";s:4:\"name\";s:9:\"Elementor\";}}}s:8:\"id-47731\";a:12:{s:5:\"title\";s:11:\"All Courses\";s:18:\"featured-image-url\";s:86:\"https://websitedemos.net/wp-content/uploads/2020/10/online-health-coach-02-courses.jpg\";s:19:\"thumbnail-image-url\";s:86:\"https://websitedemos.net/wp-content/uploads/2020/10/online-health-coach-02-courses