emos.net/wp-content/uploads/2024/04/gym-pro-04.jpg\";s:19:\"thumbnail-image-url\";s:75:\"https://websitedemos.net/wp-content/uploads/2024/04/gym-pro-04-600x3496.jpg\";s:28:\"fullpage-thumbnail-image-url\";s:75:\"https://websitedemos.net/wp-content/uploads/2024/04/gym-pro-04-400x2330.jpg\";s:14:\"astra-site-url\";s:29:\"//websitedemos.net/gym-pro-04\";s:20:\"astra-site-parent-id\";i:3598;s:15:\"astra-sites-tag\";a:12:{i:3416;s:9:\"elementor\";i:502;s:8:\"exercise\";i:499;s:7:\"fitness\";i:505;s:15:\"fitness-trainer\";i:847;s:5:\"green\";i:500;s:3:\"gym\";i:976;s:14:\"gym-instructor\";i:504;s:11:\"gym-trainer\";i:1020;s:8:\"personal\";i:1844;s:7:\"premium\";i:503;s:7:\"trainer\";i:501;s:8:\"work-out\";}s:16:\"astra-sites-type\";s:11:\"agency-mini\";s:19:\"astra-site-category\";a:1:{i:27;s:8:\"business\";}s:29:\"astra-sites-template-category\";a:1:{i:2787;s:11:\"gym-fitness\";}s:23:\"astra-site-page-builder\";s:9:\"elementor\";s:10:\"categories\";a:4:{i:3430;s:4:\"dark\";i:3427;s:7:\"default\";i:2480;s:16:\"fitness-wellness\";i:3429;s:7:\"premium\";}s:16:\"required-plugins\";a:3:{i:0;a:3:{s:4:\"slug\";s:11:\"astra-addon\";s:4:\"init\";s:27:\"astra-addon/astra-addon.php\";s:4:\"name\";s:9:\"Astra Pro\";}i:1;a:3:{s:4:\"slug\";s:9:\"elementor\";s:4:\"init\";s:23:\"elementor/elementor.php\";s:4:\"name\";s:9:\"Elementor\";}i:2;a:3:{s:4:\"slug\";s:12:\"wpforms-lite\";s:4:\"init\";s:24:\"wpforms-lite/wpforms.php\";s:4:\"name\";s:12:\"WPForms Lite\";}}s:11:\"post-status\";s:7:\"publish\";s:12:\"post-content\";s:1261:\"<!-- wp:paragraph -->\n<p>The Gym Pro template is a fantastic example of high energy design focused for a niche. Created for gyms and fitness, it reflects the industry perfectly with strong colors, bold images and that green contrast color.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Everything can be customized to suit your taste or your brand. The Gym Pro template is fully compatible with drag and drop page builders where you can customize everything you see on the page. The template is also fully responsive and will look just as amazing on small screens.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Key features of the Gym Pro template</h2>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>High energy template for gyms and fitness</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Great use of color and images throughout</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Fully responsive and works seamlessly on mobile</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Can be fully customized from the header to the footer</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Full compatibility with leading page builders</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\";s:12:\"post-excerpt\";s:71:\"The Gym Pro template uses high energy design to set the scene perfectly\";s:5:\"pages\";a:6:{s:8:\"id-88955\";a:12:{s:5:\"title\";s:4:\"Home\";s:18:\"featured-image-url\";s:66:\"https://websitedemos.net/wp-content/uploads/2024/04/gym-pro-04.jpg\";s:19:\"thumbnail-image-url\";s:75:\"https://websitedemos.net/wp-content/uploads/2024/04/gym-pro-04-600x3496.jpg\";s:18:\"astra-page-api-url\";s:59:\"https://websitedemos.net/gym-pro-04/wp-json/wp/v2/pages/322\";s:12:\"dynamic-page\";s:2:\"no\";s:14:\"astra-page-url\";s:30:\"//websitedemos.net/gym-pro-04/\";s:15:\"astra-sites-tag\";a:1:{i:423;s:4:\"home\";}s:15:\"site-pages-type\";s:11:\"agency-mini\";s:23:\"site-pages-page-builder\";s:9:\"elementor\";s:19:\"site-pages-category\";a:0:{}s:26:\"site-pages-parent-category\";a:1:{i:60;s:8:\"business\";}s:16:\"required-plugins\";a:2:{i:0;a:3:{s:4:\"slug\";s:11:\"astra-addon\";s:4:\"init\";s:27:\"astra-addon/astra-addon.php\";s:4:\"name\";s:9:\"Astra Pro\";}i:1;a:3:{s:4:\"slug\";s:9:\"elementor\";s:4:\"init\";s:23:\"elementor/elementor.php\";s:4:\"name\";s:9:\"Elementor\";}}}s:8:\"id-88952\";a:12:{s:5:\"title\";s:5:\"About\";s:18:\"featu