 -->\n<ul><!-- wp:list-item -->\n<li>Upscale design ideal for a deli or restaurant</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Attractive menu section and menu pages</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Lots of image blocks to help create an appetite</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Optional content blocks that can be fully customized</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Engaging contact page with reservation button</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Compatible with drag and drop page builders</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\";s:12:\"post-excerpt\";s:89:\"Engaging design designed around the food industry, with all essential features you expect\";s:5:\"pages\";a:6:{s:8:\"id-47163\";a:12:{s:5:\"title\";s:4:\"Home\";s:18:\"featured-image-url\";s:81:\"https://websitedemos.net/wp-content/uploads/2020/08/nyus-deli-restaurant-home.jpg\";s:19:\"thumbnail-image-url\";s:81:\"https://websitedemos.net/wp-content/uploads/2020/08/nyus-deli-restaurant-home.jpg\";s:18:\"astra-page-api-url\";s:66:\"https://websitedemos.net/deli-restaurant-02/wp-json/wp/v2/pages/18\";s:12:\"dynamic-page\";s:2:\"no\";s:14:\"astra-page-url\";s:38:\"//websitedemos.net/deli-restaurant-02/\";s:15:\"astra-sites-tag\";a:1:{i:423;s:4:\"home\";}s:15:\"site-pages-type\";s:4:\"free\";s:23:\"site-pages-page-builder\";s:9:\"elementor\";s:19:\"site-pages-category\";a:0:{}s:26:\"site-pages-parent-category\";a:2:{i:60;s:8:\"business\";i:61;s:4:\"free\";}s:16:\"required-plugins\";a:2:{i:0;a:3:{s:4:\"slug\";s:9:\"elementor\";s:4:\"init\";s:23:\"elementor/elementor.php\";s:4:\"name\";s:9:\"Elementor\";}i:1;a:3:{s:4:\"slug\";s:23:\"header-footer-elementor\";s:4:\"init\";s:51:\"header-footer-elementor/header-footer-elementor.php\";s:4:\"name\";s:33:\"Elementor Header & Footer Builder\";}}}s:8:\"id-47161\";a:12:{s:5:\"title\";s:8:\"About Us\";s:18:\"featured-image-url\";s:82:\"https://websitede