ay products based on categories, best sellers, latest arrivals, and more</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Showcase client reviews and testimonials</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Full compatibility with leading page builders</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\";s:12:\"post-excerpt\";s:87:\"Elegantly designed online store website template for selling all kinds of baby products\";s:5:\"pages\";a:4:{s:8:\"id-49346\";a:12:{s:5:\"title\";s:8:\"About Us\";s:18:\"featured-image-url\";s:76:\"https://websitedemos.net/wp-content/uploads/2020/12/baby-stores-04-about.jpg\";s:19:\"thumbnail-image-url\";s:85:\"https://websitedemos.net/wp-content/uploads/2020/12/baby-stores-04-about-600x1710.jpg\";s:18:\"astra-page-api-url\";s:62:\"https://websitedemos.net/baby-store-04/wp-json/wp/v2/pages/406\";s:12:\"dynamic-page\";s:2:\"no\";s:14:\"astra-page-url\";s:42:\"//websitedemos.net/baby-store-04/about-us/\";s:15:\"astra-sites-tag\";a:1:{i:352;s:5:\"about\";}s:15:\"site-pages-type\";s:11:\"agency-mini\";s:23:\"site-pages-page-builder\";s:9:\"elementor\";s:19:\"site-pages-category\";a:0:{}s:26:\"site-pages-parent-category\";a:2:{i:60;s:8:\"business\";i:64;s:9:\"ecommerce\";}s:16:\"required-plugins\";a:2:{i:0;a:3:{s:4:\"slug\";s:11:\"astra-addon\";s:4:\"init\";s:27:\"astra-addon/astra-addon.php\";s:4:\"name\";s:9:\"Astra Pro\";}i:1;a:3:{s:4:\"slug\";s:9:\"elementor\";s:4:\"init\";s:23:\"elementor/elementor.php\";s:4:\"name\";s:9:\"Elementor\";}}}s:8:\"id-49347\";a:12:{s:5:\"title\";s:10:\"Contact Us\";s:18:\"featured-image-url\";s:78:\"https://websitedemos.net/wp-content/uploads/2020/12/baby-stores-04-contact.jpg\";s:19:\"thumbnail-image-url\";s:87:\"https://websitedemos.net/wp-content/uploads/2020/12/baby-stores-04-contact-600x1158.jpg\";s:18:\"astra-page-api-url\";s:62:\"https://websitedemos.net/baby-store-04/wp-json/wp/v2/pages/564\";s:12:\"dynamic-page\";s:2:\"no\";s:14:\"astra-page-url\";s:44:\"//websitedemos.net/