 website template for bloggers and influencers to share travel experiences\";s:5:\"pages\";a:9:{s:8:\"id-53743\";a:12:{s:5:\"title\";s:8:\"About me\";s:18:\"featured-image-url\";s:79:\"https://websitedemos.net/wp-content/uploads/2021/05/travel-blogger-02-about.jpg\";s:19:\"thumbnail-image-url\";s:79:\"https://websitedemos.net/wp-content/uploads/2021/05/travel-blogger-02-about.jpg\";s:18:\"astra-page-api-url\";s:65:\"https://websitedemos.net/travel-blogger-04/wp-json/wp/v2/pages/19\";s:12:\"dynamic-page\";s:2:\"no\";s:14:\"astra-page-url\";s:46:\"//websitedemos.net/travel-blogger-04/about-me/\";s:15:\"astra-sites-tag\";a:1:{i:352;s:5:\"about\";}s:15:\"site-pages-type\";s:11:\"agency-mini\";s:23:\"site-pages-page-builder\";s:9:\"elementor\";s:19:\"site-pages-category\";a:0:{}s:26:\"site-pages-parent-category\";a:1:{i:74;s:4:\"blog\";}s:16:\"required-plugins\";a:1:{i:0;a:3:{s:4:\"slug\";s:9:\"elementor\";s:4:\"init\";s:23:\"elementor/elementor.php\";s:4:\"name\";s:9:\"Elementor\";}}}s:8:\"id-53744\";a:12:{s:5:\"title\";s:6:\"Africa\";s:18:\"featured-image-url\";s:80:\"https://websitedemos.net/wp-content/uploads/2021/05/travel-blogger-02-africa.jpg\";s:19:\"thumbnail-image-url\";s:80:\"https://websitedemos.net/wp-content/uploads/2021/05/travel-blogger-02-africa.jpg\";s:18:\"astra-page-api-url\";s:65:\"https://websitedemos.net/travel-blogger-04/wp-json/wp/v2/pages/29\";s:12:\"dynamic-page\";s:2:\"no\";s:14:\"astra-page-url\";s:44:\"//websitedemos.net/travel-blogger-04/africa/\";s:15:\"astra-sites-tag\";a:2:{i:2019;s:6:\"africa\";i:786;s:12:\"travel-place\";}s:15:\"site-pages-type\";s:11:\"agency-mini\";s:23:\"site-pages-page-builder\";s:9:\"elementor\";s:19:\"site-pages-category\";a:0:{}s:26:\"site-pages-parent-category\";a:1:{i:74;s:4:\"blog\";}s:16:\"required-plugins\";a:1:{i:0;a:3:{s:4:\"slug\";s:9:\"elementor\";s:4:\"init\";s:23:\"elementor/elementor.php\";s:4:\"name\";s:9:\"Elementor\";}}}s:8:\"id-53745\";a:12:{s:5:\"title\";s:4:\"Asia\";s:18:\"featured-image-url\";