graph -->\n\n<!-- wp:heading {\"UAGDay\":[]} -->\n<h2 class=\"wp-block-heading\">Key features of the Business Coaching &amp; Consulting template</h2>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Clean and professional-looking website template, perfect for a coaching and consulting business</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Well-placed CTA buttons encouraging prospective clients to connect with you</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Each of the template pages has been well thought out and designed</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>The contact page has Google maps integrated and a fully functional form</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Full compatibility with leading page builders</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\";s:12:\"post-excerpt\";s:86:\"Professional website templates tailor-made to build a coaching and consulting business\";s:5:\"pages\";a:4:{s:8:\"id-51296\";a:12:{s:5:\"title\";s:5:\"About\";s:18:\"featured-image-url\";s:84:\"https://websitedemos.net/wp-content/uploads/2021/03/business-consulting-02-about.jpg\";s:19:\"thumbnail-image-url\";s:84:\"https://websitedemos.net/wp-content/uploads/2021/03/business-consulting-02-about.jpg\";s:18:\"astra-page-api-url\";s:71:\"https://websitedemos.net/business-consulting-02/wp-json/wp/v2/pages/534\";s:12:\"dynamic-page\";s:2:\"no\";s:14:\"astra-page-url\";s:48:\"//websitedemos.net/business-consulting-02/about/\";s:15:\"astra-sites-tag\";a:1:{i:352;s:5:\"about\";}s:15:\"site-pages-type\";s:4:\"free\";s:23:\"site-pages-page-builder\";s:9:\"elementor\";s:19:\"site-pages-category\";a:0:{}s:26:\"site-pages-parent-category\";a:2:{i:60;s:8:\"business\";i:61;s:4:\"free\";}s:16:\"required-plugins\";a:2:{i:0;a:3:{s:4:\"slug\";s:9:\"elementor\";s:4:\"init\";s:23:\"elementor/elementor.php\";s:4:\"name\";s:9:\"Elementor\";}i:1;a:3:{s:4:\"slug\";s:23:\"header-footer-elementor\";s:4:\"init\