n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"UAGDay\":[]} -->\n<h2 class=\"wp-block-heading\"><strong>Key features</strong> <strong>of the Bestselling Author template</strong></h2>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Build your website using the stylish Bestselling Author template</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Promote your latest book on the homepage, above the fold</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>The template is WooCommerce ready and allows you to sell your books online</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>A fully functional contact form for readers to connect with you</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Full compatibility with leading page builders</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\";s:12:\"post-excerpt\";s:75:\"Stylish website template for authors to promote and sell their publications\";s:5:\"pages\";a:4:{s:8:\"id-51476\";a:12:{s:5:\"title\";s:4:\"Home\";s:18:\"featured-image-url\";s:82:\"https://websitedemos.net/wp-content/uploads/2021/03/bestselling-author-02-home.jpg\";s:19:\"thumbnail-image-url\";s:82:\"https://websitedemos.net/wp-content/uploads/2021/03/bestselling-author-02-home.jpg\";s:18:\"astra-page-api-url\";s:69:\"https://websitedemos.net/bestselling-author-02/wp-json/wp/v2/pages/10\";s:12:\"dynamic-page\";s:2:\"no\";s:14:\"astra-page-url\";s:41:\"//websitedemos.net/bestselling-author-02/\";s:15:\"astra-sites-tag\";a:1:{i:423;s:4:\"home\";}s:15:\"site-pages-type\";s:4:\"free\";s:23:\"site-pages-page-builder\";s:9:\"elementor\";s:19:\"site-pages-category\";a:0:{}s:26:\"site-pages-parent-category\";a:2:{i:60;s:8:\"business\";i:61;s:4:\"free\";}s:16:\"required-plugins\";a:2:{i:0;a:3:{s:4:\"slug\";s:9:\"elementor\";s:4:\"init\";s:23:\"elementor/elementor.php\";s:4:\"name\";s:9:\"Elementor\";}i:1;a:3:{s:4:\"slug\";s:23:\"header-footer-elementor\";s:4:\"init\";s:51:\"header-footer-elementor/header-foo