emos.net/digital-marketing-agency-04\";s:20:\"astra-site-parent-id\";i:2211;s:15:\"astra-sites-tag\";a:16:{i:1587;s:18:\"advertising-agency\";i:2232;s:19:\"advertising-company\";i:2229;s:16:\"advertising-firm\";i:663;s:6:\"agency\";i:979;s:7:\"company\";i:2235;s:24:\"digital-marketing-agency\";i:2036;s:22:\"digital-marketing-firm\";i:3416;s:9:\"elementor\";i:1588;s:16:\"marketing-agency\";i:2233;s:17:\"marketing-company\";i:2228;s:14:\"marketing-firm\";i:1844;s:7:\"premium\";i:2230;s:12:\"press-agency\";i:2227;s:14:\"promotion-firm\";i:2231;s:14:\"publicity-firm\";i:2234;s:18:\"publicity-services\";}s:16:\"astra-sites-type\";s:11:\"agency-mini\";s:19:\"astra-site-category\";a:1:{i:27;s:8:\"business\";}s:29:\"astra-sites-template-category\";a:5:{i:2777;s:8:\"business\";i:2794;s:10:\"consulting\";i:2812;s:14:\"digital-agency\";i:2796;s:17:\"digital-marketing\";i:2831;s:7:\"service\";}s:23:\"astra-site-page-builder\";s:9:\"elementor\";s:10:\"categories\";a:3:{i:2487;s:6:\"agency\";i:3427;s:7:\"default\";i:3429;s:7:\"premium\";}s:16:\"required-plugins\";a:3:{i:0;a:3:{s:4:\"slug\";s:9:\"elementor\";s:4:\"init\";s:23:\"elementor/elementor.php\";s:4:\"name\";s:9:\"Elementor\";}i:1;a:3:{s:4:\"slug\";s:23:\"header-footer-elementor\";s:4:\"init\";s:51:\"header-footer-elementor/header-footer-elementor.php\";s:4:\"name\";s:33:\"Elementor Header & Footer Builder\";}i:2;a:3:{s:4:\"slug\";s:12:\"wpforms-lite\";s:4:\"init\";s:24:\"wpforms-lite/wpforms.php\";s:4:\"name\";s:12:\"WPForms Lite\";}}s:11:\"post-status\";s:7:\"publish\";s:12:\"post-content\";s:1418:\"<!-- wp:paragraph -->\n<p>Itâ€™s one thing saying that it can be done and another showing that it can be done. And when it comes to letting your work do all the talking, a professionally designed website closes the deal for you with your prospective clients.&nbsp;</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Our Digital Marketing Agency template does that. The template is perfect for your agency website, from done-for-you templates showcasing all your individual services to customer reviews.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"UAGDay\":[]} -->\n<h2 class=\"wp-block-heading\">Key features of the Digital Marketing Agency template</h2>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Professionally crafted templates for your digital marketing agency website</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Package comes with individual templates for all your services, such as branding, digital marketing, SEO services, and social media</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Include customer reviews as well as ratings from Google, Facebook, and Trustpilot, among others</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Build authority and showcase your expertise by publishing regular blog posts</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Full compatibility with leading page builders</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\";s:12:\"post-excerpt\";s:82:\"Professionally crafted template best suited for a digital marketing agency website\";s:5:\"pages\";a:8:{s:8:\"id-55787\";a:12:{s:5:\"title\";s:5:\"About\";s:18:\"featured-image-url\";s:89:\"https://websitedemos.net/wp-content/uploads/2021/06/digital-marketing-agency-04-about.jpg\";s:19:\"thumbnail-image-url\";s:98:\"https://websitedemos.net/wp-content/uploads/2021/06/digital-marketing-agency-04-about-600x2017.jpg\";s:18:\"astra-page-api-url\";s:76:\"https://websitedemos.net/digital-marketing-agency-04/wp-json/wp/v2/pages/321\";s:12:\"dynamic-page\";s:2:\"no\";s:14:\"astra-page-url\";s:53:\"//websitedemos.net/digital-marketing-agency-04/about/\";s:15:\"astra-sites-tag\";a:1:{i:352;s:5:\"about\";}s:15:\"site-pages-type\";s:11:\"agency-mini\";s:23:\"site-pages-page-builder\";s:9:\"elementor\";s:19:\"site-pages-category\";a:0:{}s:26:\"site-pages-parent-category\";a:1:{i:60;s:8:\"business\";}s:16:\"required-plugins\";a:2:{i:0;a:3:{s:4