\";a:3:{i:2769;s:9:\"ecommerce\";i:2838;s:9:\"jewellery\";i:2857;s:15:\"online-shopping\";}s:23:\"astra-site-page-builder\";s:9:\"elementor\";s:10:\"categories\";a:5:{i:2479;s:6:\"beauty\";i:3427;s:7:\"default\";i:2495;s:9:\"ecommerce\";i:3434;s:8:\"feminine\";i:3429;s:7:\"premium\";}s:16:\"required-plugins\";a:6:{i:0;a:3:{s:4:\"slug\";s:9:\"elementor\";s:4:\"init\";s:23:\"elementor/elementor.php\";s:4:\"name\";s:9:\"Elementor\";}i:1;a:3:{s:4:\"slug\";s:27:\"checkout-plugins-stripe-woo\";s:4:\"init\";s:59:\"checkout-plugins-stripe-woo/checkout-plugins-stripe-woo.php\";s:4:\"name\";s:41:\"Checkout Plugins - Stripe for WooCommerce\";}i:2;a:3:{s:4:\"slug\";s:11:\"woocommerce\";s:4:\"init\";s:27:\"woocommerce/woocommerce.php\";s:4:\"name\";s:11:\"WooCommerce\";}i:3;a:3:{s:4:\"slug\";s:12:\"wpforms-lite\";s:4:\"init\";s:24:\"wpforms-lite/wpforms.php\";s:4:\"name\";s:12:\"WPForms Lite\";}i:4;a:3:{s:4:\"slug\";s:11:\"astra-addon\";s:4:\"init\";s:27:\"astra-addon/astra-addon.php\";s:4:\"name\";s:9:\"Astra Pro\";}i:5;a:3:{s:4:\"slug\";s:22:\"variation-swatches-woo\";s:4:\"init\";s:49:\"variation-swatches-woo/variation-swatches-woo.php\";s:4:\"name\";s:34:\"Variation Swatches for WooCommerce\";}}s:11:\"post-status\";s:7:\"publish\";s:12:\"post-content\";s:1116:\"<!-- wp:paragraph -->\n<p>Want to sell jewelry to a broader audience? Consider building an online store! Import our easy-to-use Jewellery Store template and launch your store quickly. Accept orders and payments round the clock through your website.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>The clean and minimalistic design has all the correct elements to help you build a high-converting store. From impressive background effects to displaying products based on categories and latest arrivals, Jewellery Store is the perfect web template for your store.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2>Key features of the Jewellery Store template</h2>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul><li