graph -->\n\n<!-- wp:paragraph -->\n<p>The template has been created for dentists, but thanks to built-in tools and page builder compatibility, you could customize it to suit any business you like. The template is fully responsive so will look amazing on any screen. Itâ€™s SEO-friendly too!</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Key features of the Dentalist template</h2>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Crisp, clean modern web template for healthcare professionals</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Fully customizable with built-in tools</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Readymade service and contact pages</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>SEO friendly and fully responsive</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Full compatibility with leading page builders</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\";s:12:\"post-excerpt\";s:79:\"The Dentalist template, designed to create trust within the healthcare industry\";s:5:\"pages\";a:4:{s:8:\"id-90967\";a:12:{s:5:\"title\";s:7:\"Contact\";s:18:\"featured-image-url\";s:76:\"https://websitedemos.net/wp-content/uploads/2024/04/dentalist-04-contact.jpg\";s:19:\"thumbnail-image-url\";s:84:\"https://websitedemos.net/wp-content/uploads/2024/04/dentalist-04-contact-600x795.jpg\";s:18:\"astra-page-api-url\";s:60:\"https://websitedemos.net/dentalist-04/wp-json/wp/v2/pages/13\";s:12:\"dynamic-page\";s:2:\"no\";s:14:\"astra-page-url\";s:40:\"//websitedemos.net/dentalist-04/contact/\";s:15:\"astra-sites-tag\";a:1:{i:415;s:7:\"contact\";}s:15:\"site-pages-type\";s:11:\"agency-mini\";s:23:\"site-pages-page-builder\";s:9:\"elementor\";s:19:\"site-pages-category\";a:0:{}s:26:\"site-pages-parent-category\";a:1:{i:60;s:8:\"business\";}s:16:\"required-plugins\";a:4:{i:0;a:3:{s:4:\"slug\";s:11:\"astra-addon\";s:4:\"init\";s:27:\"astra-addon/astra-addon.php\";s