-item -->\n\n<!-- wp:list-item -->\n<li>Reassuring colors and fonts</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Great use of light backgrounds, bold colors and images</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Relevant supplementary pages for the niche</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Full compatibility with leading page builders</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\";s:12:\"post-excerpt\";s:81:\"Well-designed website template ideal for clinics, hospitals, doctors and medicine\";s:5:\"pages\";a:5:{s:8:\"id-47550\";a:12:{s:5:\"title\";s:4:\"Home\";s:18:\"featured-image-url\";s:74:\"https://websitedemos.net/wp-content/uploads/2020/09/diagnostics-lab-04.jpg\";s:19:\"thumbnail-image-url\";s:74:\"https://websitedemos.net/wp-content/uploads/2020/09/diagnostics-lab-04.jpg\";s:18:\"astra-page-api-url\";s:66:\"https://websitedemos.net/diagnostics-lab-02/wp-json/wp/v2/pages/14\";s:12:\"dynamic-page\";s:2:\"no\";s:14:\"astra-page-url\";s:38:\"//websitedemos.net/diagnostics-lab-02/\";s:15:\"astra-sites-tag\";a:1:{i:423;s:4:\"home\";}s:15:\"site-pages-type\";s:4:\"free\";s:23:\"site-pages-page-builder\";s:9:\"elementor\";s:19:\"site-pages-category\";a:0:{}s:26:\"site-pages-parent-category\";a:2:{i:60;s:8:\"business\";i:61;s:4:\"free\";}s:16:\"required-plugins\";a:2:{i:0;a:3:{s:4:\"slug\";s:9:\"elementor\";s:4:\"init\";s:23:\"elementor/elementor.php\";s:4:\"name\";s:9:\"Elementor\";}i:1;a:3:{s:4:\"slug\";s:23:\"header-footer-elementor\";s:4:\"init\";s:51:\"header-footer-elementor/header-footer-elementor.php\";s:4:\"name\";s:33:\"Elementor Header & Footer Builder\";}}}s:8:\"id-47548\";a:12:{s:5:\"title\";s:8:\"About Us\";s:18:\"featured-image-url\";s:83:\"https://websitedemos.net/wp-content/uploads/2020/09/diagnostics-lab-02-about-us.jpg\";s:19:\"thumbnail-image-url\";s:83:\"https://websitedemos.net/wp-content/uploads/2020/09/diagnostics-lab-02-about-us.jpg\";s:18:\"astra-page-api-url\";s:67:\"https://website