7:\"premium\";i:503;s:7:\"trainer\";i:501;s:8:\"work-out\";}s:16:\"astra-sites-type\";s:11:\"agency-mini\";s:19:\"astra-site-category\";a:1:{i:27;s:8:\"business\";}s:29:\"astra-sites-template-category\";a:2:{i:2787;s:11:\"gym-fitness\";i:2770;s:8:\"personal\";}s:23:\"astra-site-page-builder\";s:9:\"elementor\";s:10:\"categories\";a:4:{i:3430;s:4:\"dark\";i:3427;s:7:\"default\";i:2480;s:16:\"fitness-wellness\";i:3429;s:7:\"premium\";}s:16:\"required-plugins\";a:4:{i:0;a:3:{s:4:\"slug\";s:11:\"astra-addon\";s:4:\"init\";s:27:\"astra-addon/astra-addon.php\";s:4:\"name\";s:9:\"Astra Pro\";}i:1;a:3:{s:4:\"slug\";s:9:\"elementor\";s:4:\"init\";s:23:\"elementor/elementor.php\";s:4:\"name\";s:9:\"Elementor\";}i:2;a:3:{s:4:\"slug\";s:18:\"ultimate-elementor\";s:4:\"init\";s:41:\"ultimate-elementor/ultimate-elementor.php\";s:4:\"name\";s:29:\"Ultimate Addons for Elementor\";}i:3;a:3:{s:4:\"slug\";s:12:\"wpforms-lite\";s:4:\"init\";s:24:\"wpforms-lite/wpforms.php\";s:4:\"name\";s:12:\"WPForms Lite\";}}s:11:\"post-status\";s:7:\"publish\";s:12:\"post-content\";s:1312:\"<!-- wp:paragraph -->\n<p>The John\'s Fitness Hub template is designed to portray the energy and enthusiasm of the industry to help attract new clients and help them change their lives. It uses vibrant colors and images to paint the picture of a healthy lifestyle.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>While created for fitness, the template could easily be customized to suit any business. It is fully compatible with popular page builders and includes built-in tools to help you change everything you see on the page. The template is also fully responsive and SEO friendly so all bases are covered.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Key features of the John\'s Fitness Hub template</h2>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Vibrant web template for fitness and activity businesses</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Uses lots of images and effects for engagement</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Can be fully customized with built-in tools</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>SEO friendly and fully responsive</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Full compatibility with leading page builders</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\";s:12:\"post-excerpt\";s:90:\"The Fitness Hub website template is designed to help you help others transform their lives\";s:5:\"pages\";a:5:{s:8:\"id-90800\";a:12:{s:5:\"title\";s:5:\"About\";s:18:\"featured-image-url\";s:76:\"https://websitedemos.net/wp-content/uploads/2024/04/fitness-hub-04-about.jpg\";s:19:\"thumbnail-image-url\";s:85:\"https://websitedemos.net/wp-content/uploads/2024/04/fitness-hub-04-about-600x2388.jpg\";s:18:\"astra-page-api-url\";s:62:\"https://websitedemos.net/fitness-hub-04/wp-json/wp/v2/pages/21\";s:12:\"dynamic-page\";s:2:\"no\";s:14:\"astra-page-url\";s:40:\"//websitedemos.net/fitness-hub-04/about/\";s:15:\"astra-sites-tag\";a:1:{i:352;s:5:\"about\";}s:15:\"site-pages-type\";s:11:\"agency-mini\";s:23:\"site-pages-page-builder\";s:9:\"elementor\";s:19:\"site-pages-category\";a:0:{}s:26:\"site-pages-parent-category\";a:1:{i:60;s:8:\"business\";}s:16:\"required-plugins\";a:4:{i:0;a:3:{s:4:\"slug\";s:11:\"astra-addon\";s:4:\"init\";s:27:\"astra-addon/astra-addon.php\";s:4:\"name\";s:9:\"Astra Pro\";}i:1;a:3:{s:4:\"slug\";s:9:\"elementor\";s:4:\"init\";s:23:\"elementor/elementor.php\";s:4:\"name\";s:9:\"Elementor\";}i:2;a:3:{s:4:\"slug\";s:18:\"ultimate-elementor\";s:4:\"init\";s:41:\"ultimate-elementor/ultimate-elementor.php\";s:4:\"name\";s:29:\"Ultimate Addons for Elementor\";}i:3;a:3:{s:4:\"slug\";s:12:\"wpforms-lite\";s:4:\"init\";s:24:\"wpforms-lite/wpforms.php\";s:4:\"name\";s:12:\"WPForms Lite\";}}}s:8:\"id-90804\";a:12:{s:5:\"title\";s:14:\"Training Rates\";s:18:\"featured-image-url\";s:79:\"https://websitedemos.net/