uploads/2020/01/winery-04-homepage-screenshot.jpg\";s:19:\"thumbnail-image-url\";s:85:\"https://websitedemos.net/wp-content/uploads/2020/01/winery-04-homepage-screenshot.jpg\";s:28:\"fullpage-thumbnail-image-url\";s:85:\"https://websitedemos.net/wp-content/uploads/2020/01/winery-04-homepage-screenshot.jpg\";s:14:\"astra-site-url\";s:28:\"//websitedemos.net/winery-04\";s:20:\"astra-site-parent-id\";i:1115;s:15:\"astra-sites-tag\";a:6:{i:635;s:7:\"brewery\";i:3416;s:9:\"elementor\";i:632;s:7:\"farming\";i:1844;s:7:\"premium\";i:1019;s:14:\"wine-prouction\";i:633;s:6:\"winery\";}s:16:\"astra-sites-type\";s:11:\"agency-mini\";s:19:\"astra-site-category\";a:1:{i:27;s:8:\"business\";}s:29:\"astra-sites-template-category\";a:2:{i:2777;s:8:\"business\";i:2813;s:6:\"winery\";}s:23:\"astra-site-page-builder\";s:9:\"elementor\";s:10:\"categories\";a:4:{i:3427;s:7:\"default\";i:2474;s:13:\"manufacturing\";i:3429;s:7:\"premium\";i:2496;s:15:\"restaurant-food\";}s:16:\"required-plugins\";a:1:{i:0;a:3:{s:4:\"slug\";s:9:\"elementor\";s:4:\"init\";s:23:\"elementor/elementor.php\";s:4:\"name\";s:9:\"Elementor\";}}s:11:\"post-status\";s:7:\"publish\";s:12:\"post-content\";s:948:\"<!-- wp:paragraph -->\n<p>The Winery template makes its case immediately with a high quality image in the header. The rest of the homepage combines dark, light and a red contrast color to create that feeling of luxury youâ€™re looking for.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>The template has a superb layout with plenty of opportunities to tell your story, share products and services and communicate with your audience. The supplementary pages are equally attractive, helping to keep a coherent feel throughout.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2>Key features of the Winery template</h2>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul><li>Design makes an instant impact with that header</li><li>Innovative layout with interesting content areas</li><li>Great mix of dark, light and colors</li><li>Supplementary pages ideal for the niche</li><li>Full compatibility with leading page builders</li></ul>\n<!-- /wp:list -->\";s:12:\"post-excerpt\";s:80:\"Classy web template that sets the scene for vineyards, vintners and wine sellers\";s:5:\"pages\";a:5:{s:8:\"id-38623\";a:12:{s:5:\"title\";s:4:\"Home\";s:18:\"featured-image-url\";s:85:\"https://websitedemos.net/wp-content/uploads/2020/01/winery-04-homepage-screenshot.jpg\";s:19:\"thumbnail-image-url\";s:85:\"https://websitedemos.net/wp-content/uploads/2020/01/winery-04-homepage-screenshot.jpg\";s:18:\"astra-page-api-url\";s:57:\"https://websitedemos.net/winery-04/wp-json/wp/v2/pages/11\";s:12:\"dynamic-page\";s:2:\"no\";s:14:\"astra-page-url\";s:29:\"//websitedemos.net/winery-04/\";s:15:\"astra-sites-tag\";a:1:{i:423;s:4:\"home\";}s:15:\"site-pages-type\";s:11:\"agency-mini\";s:23:\"site-pages-page-builder\";s:9:\"elementor\";s:19:\"site-pages-category\";a:0:{}s:26:\"site-pages-parent-category\";a:1:{i:60;s:8:\"business\";}s:16:\"required-plugins\";a:1:{i:0;a:3:{s:4:\"slug\";s:9:\"elementor\";s:4:\"init\";s:23:\"elementor/elementor.php\";s:4:\"name\";s:9:\"Elementor\";}}}s:8:\"id-38624\";a:12:{s:5:\"title\";s:9:\"Our Story\";s:18:\"featured-image-url\";s:86:\"https://websitedemos.net/wp-content/uploads/2020/01/winery-04-our-story-screenshot.jpg\";s:19:\"thumbnail-image-url\";s:86:\"https://websitedemos.net/wp-content/uploads/2020/01/winery-04-our-story-screenshot.jpg\";s:18:\"astra-page-api-url\";s:57:\"https://websitedemos.net/winery-04/wp-json/wp/v2/pages/22\";s:12:\"dynamic-page\";s:2:\"no\";s:14:\"astra-page-url\";s:39:\"//websitedemos.net/winery-04/our-story/\";s:15:\"astra-sites-tag\";a:2:{i:352;s:5:\"about\";i:905;s:9:\"our-story\";}s:15:\"site-pages-type\";s:11:\"agency-mini\";s:23:\"site-pages-page-builder\";s:9:\"elementor\";s:19:\"site-pages-category\";a:0:{}s:26:\"site-pages-parent-category\";a:1:{i:60;s:8:\"business\";}s:16:\"required-plugins\";a:1:{i:0;a:3:{s:4:\"slug\";s:9:\"elem