:list-item -->\n<li>Atmospheric template for food businesses</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Nice layout with smooth flow down the page</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Parallax scrolling makes the design stand out</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>SEO friendly and fully responsive</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Full compatibility with leading page builders</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\";s:12:\"post-excerpt\";s:76:\"The Restaurant BBQ template helps create an appetite for your food business\n\";s:5:\"pages\";a:4:{s:8:\"id-87380\";a:12:{s:5:\"title\";s:4:\"Menu\";s:18:\"featured-image-url\";s:82:\"https://websitedemos.net/wp-content/uploads/2024/02/restaurant-bbq-02-our-menu.jpg\";s:19:\"thumbnail-image-url\";s:91:\"https://websitedemos.net/wp-content/uploads/2024/02/restaurant-bbq-02-our-menu-600x1606.jpg\";s:18:\"astra-page-api-url\";s:66:\"https://websitedemos.net/restaurant-bbq-02/wp-json/wp/v2/pages/296\";s:12:\"dynamic-page\";s:2:\"no\";s:14:\"astra-page-url\";s:42:\"//websitedemos.net/restaurant-bbq-02/menu/\";s:15:\"astra-sites-tag\";a:1:{i:565;s:4:\"menu\";}s:15:\"site-pages-type\";s:4:\"free\";s:23:\"site-pages-page-builder\";s:9:\"elementor\";s:19:\"site-pages-category\";a:0:{}s:26:\"site-pages-parent-category\";a:1:{i:60;s:8:\"business\";}s:16:\"required-plugins\";a:2:{i:0;a:3:{s:4:\"slug\";s:9:\"elementor\";s:4:\"init\";s:23:\"elementor/elementor.php\";s:4:\"name\";s:9:\"Elementor\";}i:1;a:3:{s:4:\"slug\";s:23:\"header-footer-elementor\";s:4:\"init\";s:51:\"header-footer-elementor/header-footer-elementor.php\";s:4:\"name\";s:33:\"Elementor Header & Footer Builder\";}}}s:8:\"id-87379\";a:12:{s:5:\"title\";s:4:\"Home\";s:18:\"featured-image-url\";s:73:\"https://websitedemos.net/wp-content/uploads/2024/02/restaurant-bbq-02.jpg\";s:19:\"thumbnail-image-url\";s:82:\"https://websitedemos.net/wp-content/uploads/2024/02/restaurant-bbq