st-item -->\n<li>Simple to install and set up</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Full compatibility with leading page builders</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\";s:12:\"post-excerpt\";s:71:\"The Flower Shop template is ideal for budding florists and flower shops\";s:5:\"pages\";a:3:{s:8:\"id-87544\";a:12:{s:5:\"title\";s:5:\"About\";s:18:\"featured-image-url\";s:76:\"https://websitedemos.net/wp-content/uploads/2024/02/flower-shop-04-about.jpg\";s:19:\"thumbnail-image-url\";s:85:\"https://websitedemos.net/wp-content/uploads/2024/02/flower-shop-04-about-600x2278.jpg\";s:18:\"astra-page-api-url\";s:63:\"https://websitedemos.net/flower-shop-04/wp-json/wp/v2/pages/287\";s:12:\"dynamic-page\";s:2:\"no\";s:14:\"astra-page-url\";s:40:\"//websitedemos.net/flower-shop-04/about/\";s:15:\"astra-sites-tag\";a:1:{i:352;s:5:\"about\";}s:15:\"site-pages-type\";s:11:\"agency-mini\";s:23:\"site-pages-page-builder\";s:9:\"elementor\";s:19:\"site-pages-category\";a:0:{}s:26:\"site-pages-parent-category\";a:1:{i:64;s:9:\"ecommerce\";}s:16:\"required-plugins\";a:2:{i:0;a:3:{s:4:\"slug\";s:11:\"astra-addon\";s:4:\"init\";s:27:\"astra-addon/astra-addon.php\";s:4:\"name\";s:9:\"Astra Pro\";}i:1;a:3:{s:4:\"slug\";s:9:\"elementor\";s:4:\"init\";s:23:\"elementor/elementor.php\";s:4:\"name\";s:9:\"Elementor\";}}}s:8:\"id-87545\";a:12:{s:5:\"title\";s:7:\"Contact\";s:18:\"featured-image-url\";s:78:\"https://websitedemos.net/wp-content/uploads/2024/02/flower-shop-04-contact.jpg\";s:19:\"thumbnail-image-url\";s:87:\"https://websitedemos.net/wp-content/uploads/2024/02/flower-shop-04-contact-600x1378.jpg\";s:18:\"astra-page-api-url\";s:63:\"https://websitedemos.net/flower-shop-04/wp-json/wp/v2/pages/288\";s:12:\"dynamic-page\";s:2:\"no\";s:14:\"astra-page-url\";s:42:\"//websitedemos.net/flower-shop-04/contact/\";s:15:\"astra-sites-tag\";a:1:{i:415;s:7:\"contact\";}s:15:\"site-pages-type\";s:11:\"agency-mini\";s:23:\"site-pages-page-builder\";s:9:\"elemento