 -->\n<h2 class=\"wp-block-heading\">Key features of the Pet Services template</h2>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Emotive image to being building relationships</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Great use of whitespace on all pages</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Default colors and fonts work well</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Option to accept donations through the website</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Full compatibility with leading page builders</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\";s:12:\"post-excerpt\";s:84:\"Emotive template that could be used for any type of pet shop or pet services company\";s:5:\"pages\";a:4:{s:8:\"id-22679\";a:12:{s:5:\"title\";s:4:\"Home\";s:18:\"featured-image-url\";s:76:\"https://websitedemos.net/wp-content/uploads/2019/07/pet-sitting-homepage.jpg\";s:19:\"thumbnail-image-url\";s:76:\"https://websitedemos.net/wp-content/uploads/2019/07/pet-sitting-homepage.jpg\";s:18:\"astra-page-api-url\";s:62:\"https://websitedemos.net/pet-sitting-02/wp-json/wp/v2/pages/15\";s:12:\"dynamic-page\";s:2:\"no\";s:14:\"astra-page-url\";s:34:\"//websitedemos.net/pet-sitting-02/\";s:15:\"astra-sites-tag\";a:1:{i:423;s:4:\"home\";}s:15:\"site-pages-type\";s:4:\"free\";s:23:\"site-pages-page-builder\";s:9:\"elementor\";s:19:\"site-pages-category\";a:0:{}s:26:\"site-pages-parent-category\";a:2:{i:60;s:8:\"business\";i:61;s:4:\"free\";}s:16:\"required-plugins\";a:2:{i:0;a:3:{s:4:\"slug\";s:9:\"elementor\";s:4:\"init\";s:23:\"elementor/elementor.php\";s:4:\"name\";s:9:\"Elementor\";}i:1;a:3:{s:4:\"slug\";s:23:\"header-footer-elementor\";s:4:\"init\";s:51:\"header-footer-elementor/header-footer-elementor.php\";s:4:\"name\";s:33:\"Elementor Header & Footer Builder\";}}}s:8:\"id-22676\";a:12:{s:5:\"title\";s:8:\"About Us\";s:18:\"featured-image-url\";s:77:\"https://websitedemos.net/wp-content/uploads