8;s:16:\"community-center\";i:1013;s:8:\"donation\";i:3416;s:9:\"elementor\";i:2124;s:17:\"environmental-ngo\";i:624;s:10:\"foundation\";i:977;s:10:\"non-profit\";i:745;s:12:\"organization\";i:2127;s:10:\"social-ngo\";}s:16:\"astra-sites-type\";s:4:\"free\";s:19:\"astra-site-category\";a:2:{i:39;s:4:\"free\";i:36;s:5:\"other\";}s:29:\"astra-sites-template-category\";a:4:{i:2786;s:17:\"charity-nonprofit\";i:2864;s:9:\"community\";i:2872;s:19:\"donation-fundraiser\";i:2871;s:3:\"ngo\";}s:23:\"astra-site-page-builder\";s:9:\"elementor\";s:10:\"categories\";a:3:{i:3427;s:7:\"default\";i:3428;s:4:\"free\";i:2492;s:10:\"non-profit\";}s:16:\"required-plugins\";a:2:{i:0;a:3:{s:4:\"slug\";s:9:\"elementor\";s:4:\"init\";s:23:\"elementor/elementor.php\";s:4:\"name\";s:9:\"Elementor\";}i:1;a:3:{s:4:\"slug\";s:12:\"wpforms-lite\";s:4:\"init\";s:24:\"wpforms-lite/wpforms.php\";s:4:\"name\";s:12:\"WPForms Lite\";}}s:11:\"post-status\";s:7:\"publish\";s:12:\"post-content\";s:1261:\"<!-- wp:paragraph -->\n<p>The Charity template starts strong with an emotive full screen image and bold headline. Scroll past and the homepage opens up with lots of whitespace, complementing colors and a range of content areas to share the story of your charity or nonprofit.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Pages include a biography section, areas to share your good works, an image gallery and a donation section. All these can be fully customized to suit your particular needs. As can the equally attractive, and effective, supplementary pages.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"UAGDay\":[]} -->\n<h2 class=\"wp-block-heading\">Key features of the Charity template</h2>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Powerful opening ideal for emotive subjects</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Great use of complementing colors and fonts</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Lots of options for images and storytelling</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Donation section included within each page</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Full compatibility with leading page builders</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\";s:12:\"post-excerpt\";s:78:\"Well-designed template perfect for charities and nonprofits to raise awareness\";s:5:\"pages\";a:4:{s:8:\"id-55335\";a:12:{s:5:\"title\";s:5:\"About\";s:18:\"featured-image-url\";s:76:\"https://websitedemos.net/wp-content/uploads/2021/05/communities-02-about.jpg\";s:19:\"thumbnail-image-url\";s:76:\"https://websitedemos.net/wp-content/uploads/2021/05/communities-02-about.jpg\";s:18:\"astra-page-api-url\";s:62:\"https://websitedemos.net/communities-02/wp-json/wp/v2/pages/15\";s:12:\"dynamic-page\";s:2:\"no\";s:14:\"astra-page-url\";s:40:\"//websitedemos.net/communities-02/about/\";s:15:\"astra-sites-tag\";a:1:{i:352;s:5:\"about\";}s:15:\"site-pages-type\";s:4:\"free\";s:23:\"site-pages-page-builder\";s:9:\"elementor\";s:19:\"site-pages-category\";a:0:{}s:26:\"site-pages-parent-category\";a:2:{i:61;s:4:\"free\";i:139;s:5:\"other\";}s:16:\"required-plugins\";a:1:{i:0;a:3:{s:4:\"slug\";s:9:\"elementor\";s:4:\"init\";s:23:\"elementor/elementor.php\";s:4:\"name\";s:9:\"Elementor\";}}}s:8:\"id-55336\";a:12:{s:5:\"title\";s:7:\"Contact\";s:18:\"featured-image-url\";s:78:\"https://websitedemos.net/wp-content/uploads/2021/05/communities-02-contact.jpg\";s:19:\"thumbnail-image-url\";s:78:\"https://websitedemos.net/wp-content/uploads/2021/05/communities-02-contact.jpg\";s:18:\"astra-page-api-url\";s:62:\"https://websitedemos.net/communities-02/wp-json/wp/v2/pages/19\";s:12:\"dynamic-page\";s:2:\"no\";s:14:\"astra-page-url\";s:42:\"//websitedemos.net/communities-02/contact/\";s:15:\"astra-sites-tag\";a:1:{i:415;s:7:\"contact\";}s:15:\"site-pages-type\";s:4:\"free\";s:23:\"site-pages-page-builder\";s:9:\"elementor\";s:19:\"site-pages-category\";a:0:{}s:26:\"site-pages-parent-