tedemos.net/multimed-04\";s:20:\"astra-site-parent-id\";i:261;s:15:\"astra-sites-tag\";a:9:{i:337;s:6:\"clinic\";i:601;s:6:\"doctor\";i:3416;s:9:\"elementor\";i:604;s:10:\"healthcare\";i:605;s:8:\"hospital\";i:603;s:7:\"medical\";i:606;s:15:\"medical-science\";i:1844;s:7:\"premium\";i:607;s:9:\"treatment\";}s:16:\"astra-sites-type\";s:11:\"agency-mini\";s:19:\"astra-site-category\";a:1:{i:27;s:8:\"business\";}s:29:\"astra-sites-template-category\";a:4:{i:2867;s:6:\"doctor\";i:2834;s:10:\"healthcare\";i:2780;s:8:\"hospital\";i:2841;s:14:\"medical-clinic\";}s:23:\"astra-site-page-builder\";s:9:\"elementor\";s:10:\"categories\";a:3:{i:3427;s:7:\"default\";i:2490;s:10:\"healthcare\";i:3429;s:7:\"premium\";}s:16:\"required-plugins\";a:2:{i:0;a:3:{s:4:\"slug\";s:9:\"elementor\";s:4:\"init\";s:23:\"elementor/elementor.php\";s:4:\"name\";s:9:\"Elementor\";}i:1;a:3:{s:4:\"slug\";s:12:\"wpforms-lite\";s:4:\"init\";s:24:\"wpforms-lite/wpforms.php\";s:4:\"name\";s:12:\"WPForms Lite\";}}s:11:\"post-status\";s:7:\"publish\";s:12:\"post-content\";s:1019:\"<!-- wp:paragraph -->\n<p>The MultiMed Clinic template engages instantly with a simple header with shaded background image. The use of colors related to medicine tells you exactly what this design is all about, without saying a word.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Talking of words, there are flexible content areas throughout that you can customize to suit your clinic. You can effortlessly outline products and services, surgery times, opening hours, departments and all the information you need to communicate with your audience.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2>Key features of the MultiMed Clinic template</h2>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul><li>Bold opening with colors linked to medicine</li><li>Instantly communicates a message before you read a word</li><li>Customizable content areas throughout the template</li><li>Includes most sections you would expect to see for a clinic</li><li>Full compatibility with leading page builders</li></ul>\n<!-- /wp:list -->\";s:12:\"post-excerpt\";s:81:\"Clean, modern medical website template ideal for clinics, surgeries and hospitals\";s:5:\"pages\";a:6:{s:8:\"id-24729\";a:12:{s:5:\"title\";s:4:\"Home\";s:18:\"featured-image-url\";s:72:\"https://websitedemos.net/wp-content/uploads/2019/07/multimed-04-home.jpg\";s:19:\"thumbnail-image-url\";s:72:\"https://websitedemos.net/wp-content/uploads/2019/07/multimed-04-home.jpg\";s:18:\"astra-page-api-url\";s:58:\"https://websitedemos.net/multimed-04/wp-json/wp/v2/pages/6\";s:12:\"dynamic-page\";s:2:\"no\";s:14:\"astra-page-url\";s:31:\"//websitedemos.net/multimed-04/\";s:15:\"astra-sites-tag\";a:1:{i:423;s:4:\"home\";}s:15:\"site-pages-type\";s:11:\"agency-mini\";s:23:\"site-pages-page-builder\";s:9:\"elementor\";s:19:\"site-pages-category\";a:0:{}s:26:\"site-pages-parent-category\";a:1:{i:60;s:8:\"business\";}s:16:\"required-plugins\";a:1:{i:0;a:3:{s:4:\"slug\";s:9:\"elementor\";s:4:\"init\";s:23:\"elementor/elementor.php\";s:4:\"name\";s:9:\"Elementor\";}}}s:8:\"id-24724\";a:12:{s:5:\"title\";s:5:\"About\";s:18:\"featured-image-url\";s:73:\"https://websitedemos.net/wp-content/uploads/2019/07/multimed-04-about.jpg\";s:19:\"thumbnail-image-url\";s:73:\"https://websitedemos.net/wp-content/uploads/2019/07/multimed-04-about.jpg\";s:18:\"astra-page-api-url\";s:58:\"https://websitedemos.net/multimed-04/wp-json/wp/v2/pages/7\";s:12:\"dynamic-page\";s:2:\"no\";s:14:\"astra-page-url\";s:37:\"//websitedemos.net/multimed-04/about/\";s:15:\"astra-sites-tag\";a:1:{i:352;s:5:\"about\";}s:15:\"site-pages-type\";s:11:\"agency-mini\";s:23:\"site-pages-page-builder\";s:9:\"elementor\";s:19:\"site-pages-category\";a:0:{}s:26:\"site-pages-parent-category\";a:1:{i:60;s:8:\"business\";}s:16:\"required-plugins\";a:1:{i:0;a:3:{s:4:\"slug\";s:9:\"elementor\";s:4:\"init\";s:23:\"elementor/elementor.php\";s:4:\"name\";s:9:\"Elementor\";}}}s:8:\"id-24727\";a:12:{s:5:\"title\";s:11