ame\";s:9:\"Elementor\";}i:1;a:3:{s:4:\"slug\";s:18:\"ultimate-elementor\";s:4:\"init\";s:41:\"ultimate-elementor/ultimate-elementor.php\";s:4:\"name\";s:29:\"Ultimate Addons for Elementor\";}i:2;a:3:{s:4:\"slug\";s:11:\"woocommerce\";s:4:\"init\";s:27:\"woocommerce/woocommerce.php\";s:4:\"name\";s:11:\"WooCommerce\";}i:3;a:3:{s:4:\"slug\";s:29:\"woo-cart-abandonment-recovery\";s:4:\"init\";s:63:\"woo-cart-abandonment-recovery/woo-cart-abandonment-recovery.php\";s:4:\"name\";s:37:\"WooCommerce Cart Abandonment Recovery\";}i:4;a:3:{s:4:\"slug\";s:12:\"wpforms-lite\";s:4:\"init\";s:24:\"wpforms-lite/wpforms.php\";s:4:\"name\";s:12:\"WPForms Lite\";}i:5;a:3:{s:4:\"slug\";s:11:\"astra-addon\";s:4:\"init\";s:27:\"astra-addon/astra-addon.php\";s:4:\"name\";s:9:\"Astra Pro\";}i:6;a:3:{s:4:\"slug\";s:22:\"variation-swatches-woo\";s:4:\"init\";s:49:\"variation-swatches-woo/variation-swatches-woo.php\";s:4:\"name\";s:34:\"Variation Swatches for WooCommerce\";}}s:11:\"post-status\";s:7:\"publish\";s:12:\"post-content\";s:1262:\"<!-- wp:paragraph -->\n<p>The Ayurveda template has been created for the health and wellness niche. It uses calm colors, high quality images and a mixture of attractive fonts to make you feel instantly welcome and receptive to the message.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>The use of green, while customizable, helps create a feeling of relaxation expected of the niche. All pages combine content areas, whitespace, calls to action, images and content to help engage. The web template can integrate seamlessly with WooCommerce to create a fully working online store too!</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2>Key features of the Ayurveda template</h2>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Relaxed design ideal for health and wellness</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Laid back vibe while delivering your core message</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-