raph -->\n\n<!-- wp:heading -->\n<h2>Key features of the Author template</h2>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul><li>Calm, composed website design</li><li>Configured for creatives to showcase their work</li><li>Tasteful color and font choices throughout</li><li>Book pages let you add a lot of detail</li><li>Full compatibility with leading page builders</li></ul>\n<!-- /wp:list -->\";s:12:\"post-excerpt\";s:83:\"Tasteful web template for freelancers, creatives or agencies to show off their work\";s:5:\"pages\";a:4:{s:8:\"id-24419\";a:12:{s:5:\"title\";s:4:\"Home\";s:18:\"featured-image-url\";s:67:\"https://websitedemos.net/wp-content/uploads/2019/07/author-home.jpg\";s:19:\"thumbnail-image-url\";s:67:\"https://websitedemos.net/wp-content/uploads/2019/07/author-home.jpg\";s:18:\"astra-page-api-url\";s:56:\"https://websitedemos.net/author-04/wp-json/wp/v2/pages/6\";s:12:\"dynamic-page\";s:2:\"no\";s:14:\"astra-page-url\";s:29:\"//websitedemos.net/author-04/\";s:15:\"astra-sites-tag\";a:1:{i:423;s:4:\"home\";}s:15:\"site-pages-type\";s:11:\"agency-mini\";s:23:\"site-pages-page-builder\";s:9:\"elementor\";s:19:\"site-pages-category\";a:0:{}s:26:\"site-pages-parent-category\";a:1:{i:60;s:8:\"business\";}s:16:\"required-plugins\";a:1:{i:0;a:3:{s:4:\"slug\";s:9:\"elementor\";s:4:\"init\";s:23:\"elementor/elementor.php\";s:4:\"name\";s:9:\"Elementor\";}}}s:8:\"id-24417\";a:12:{s:5:\"title\";s:5:\"Books\";s:18:\"featured-image-url\";s:68:\"https://websitedemos.net/wp-content/uploads/2019/07/author-books.jpg\";s:19:\"thumbnail-image-url\";s:68:\"https://websitedemos.net/wp-content/uploads/2019/07/author-books.jpg\";s:18:\"astra-page-api-url\";s:56:\"https://websitedemos.net/author-04/wp-json/wp/v2/pages/7\";s:12:\"dynamic-page\";s:2:\"no\";s:14:\"astra-page-url\";s:35:\"//websitedemos.net/author-04/books/\";s:15:\"astra-sites-tag\";a:1:{i:727;s:4:\"book\";}s:15:\"site-pages-type\";s:11:\"agency-mini\";s:23:\"site-pages-page-builder\";s:9:\"elementor\";s:19:\"site-p