estyle</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Lovely colors and fonts</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Good use of images throughout the design</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Can be customized to suit any use with minimal effort</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Full compatibility with drag and drop page builders</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\";s:12:\"post-excerpt\";s:81:\"Lifestyle blog template design to instantly create a connection with the audience\";s:5:\"pages\";a:3:{s:8:\"id-23319\";a:12:{s:5:\"title\";s:4:\"Home\";s:18:\"featured-image-url\";s:85:\"https://websitedemos.net/wp-content/uploads/2019/07/fashion-lifestyle-02-homepage.jpg\";s:19:\"thumbnail-image-url\";s:85:\"https://websitedemos.net/wp-content/uploads/2019/07/fashion-lifestyle-02-homepage.jpg\";s:18:\"astra-page-api-url\";s:69:\"https://websitedemos.net/fashion-lifestyle-02/wp-json/wp/v2/pages/855\";s:12:\"dynamic-page\";s:2:\"no\";s:14:\"astra-page-url\";s:40:\"//websitedemos.net/fashion-lifestyle-02/\";s:15:\"astra-sites-tag\";a:1:{i:423;s:4:\"home\";}s:15:\"site-pages-type\";s:4:\"free\";s:23:\"site-pages-page-builder\";s:9:\"elementor\";s:19:\"site-pages-category\";a:0:{}s:26:\"site-pages-parent-category\";a:2:{i:74;s:4:\"blog\";i:61;s:4:\"free\";}s:16:\"required-plugins\";a:2:{i:0;a:3:{s:4:\"slug\";s:13:\"astra-widgets\";s:4:\"init\";s:31:\"astra-widgets/astra-widgets.php\";s:4:\"name\";s:13:\"Astra Widgets\";}i:1;a:3:{s:4:\"slug\";s:9:\"elementor\";s:4:\"init\";s:23:\"elementor/elementor.php\";s:4:\"name\";s:9:\"Elementor\";}}}s:8:\"id-23317\";a:12:{s:5:\"title\";s:4:\"Blog\";s:18:\"featured-image-url\";s:81:\"https://websitedemos.net/wp-content/uploads/2019/07/fashion-lifestyle-02-blog.jpg\";s:19:\"thumbnail-image-url\";s:81:\"https://websitedemos.net/wp-content/uploads/2019/07/fashion-lifestyle-02-blog.jpg\";s:18:\"astra-page-api-url\";s:67:\"https://websitedemos.net/