UAGDay\":[]} -->\n<h2 class=\"wp-block-heading\">Key features of the Prime Lawyers template</h2>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Well-designed template ideal for the legal profession</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Suitable for law firms, individual lawyers or legal advice</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Lots of areas to outline services and expertise</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Can be customized to suit any brand identity</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Great balance between light and dark</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Full compatibility with drag and drop page builders</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\";s:12:\"post-excerpt\";s:84:\"Professional template with sober colors, nice layout and confidence-inspiring design\";s:5:\"pages\";a:5:{s:8:\"id-24652\";a:12:{s:5:\"title\";s:4:\"Home\";s:18:\"featured-image-url\";s:73:\"https://websitedemos.net/wp-content/uploads/2019/07/law-firm-homepage.jpg\";s:19:\"thumbnail-image-url\";s:73:\"https://websitedemos.net/wp-content/uploads/2019/07/law-firm-homepage.jpg\";s:18:\"astra-page-api-url\";s:53:\"https://websitedemos.net/law-02/wp-json/wp/v2/pages/7\";s:12:\"dynamic-page\";s:2:\"no\";s:14:\"astra-page-url\";s:26:\"//websitedemos.net/law-02/\";s:15:\"astra-sites-tag\";a:1:{i:423;s:4:\"home\";}s:15:\"site-pages-type\";s:4:\"free\";s:23:\"site-pages-page-builder\";s:9:\"elementor\";s:19:\"site-pages-category\";a:0:{}s:26:\"site-pages-parent-category\";a:2:{i:60;s:8:\"business\";i:61;s:4:\"free\";}s:16:\"required-plugins\";a:1:{i:0;a:3:{s:4:\"slug\";s:9:\"elementor\";s:4:\"init\";s:23:\"elementor/elementor.php\";s:4:\"name\";s:9:\"Elementor\";}}}s:8:\"id-24648\";a:12:{s:5:\"title\";s:5:\"About\";s:18:\"featured-image-url\";s:72:\"https://websitedemos.net/wp-content/uploads/2019/07/law-firm-aboutus.jpg\";s:19:\"thumbnail-image-u