0,\"columnGapDesktop\":0,\"columnGapTablet\":0} -->\n<div class=\"wp-block-uagb-container uagb-block-307ef329\"><!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\"}} -->\n<div class=\"wp-block-group\"><!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">1. Research and Development</h3>\n<!-- /wp:heading --></div>\n<!-- /wp:group -->\n\n<!-- wp:paragraph -->\n<p>Research and Development are the core of our approach to innovation. Conduct feasibility studies for new shipping routes and methods, among other research, we identify and develop new technologies and solutions to improve efficiency, safety and sustainability in the shipping of oil and gas products.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\"}} -->\n<div class=\"wp-block-group\"><!-- wp:heading -->\n<h2 class=\"wp-block-heading\">2. Creative Solutions</h2>\n<!-- /wp:heading --></div>\n<!-- /wp:group -->\n\n<!-- wp:paragraph -->\n<p>From rethinking existing processes to exploring alternative approaches to traditional methods, we constantly seek new ways to increase client visibility and value delivery. We also look to get the most out of advances in digitalization.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:uagb/container -->\n\n<!-- wp:group {\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\"><!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\"}} -->\n<div class=\"wp-block-group\"><!-- wp:uagb/advanced-heading {\"block_id\":\"20e34ff8\",\"classMigrate\":true} -->\n<div class=\"wp-block-uagb-advanced-heading uagb-block-20e34ff8\"><h2 class=\"uagb-heading-text\">3. Team Spirit</h2></div>\n<!-- /wp:uagb/advanced-heading --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:paragraph -->\n<p>Our specially selected team comes with much creative energy to deliver top-notch services to our clients through attention to details, technical proficiency, energy and other relevant industry skills.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:heading -->\n<h2 class=\"wp-block-heading\">4. Project Execution</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>To effectively execute projects, we have well-defined project management processes, uniquely tailored to the need of individual clients for maximum customer satisfaction.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div></div>\n<!-- /wp:uagb/container -->','Our Work Process - Forthouse','','publish','closed','closed','','our-work-process-forthouse','','','2023-12-19 11:45:38','2023-12-19 11:45:38','',0,'https://fral.neovisage.com/our-work-process-forthouse/',0,'wp_block','',0),(719,1,'2023-12-19 11:45:38','2023-12-19 11:45:38','<!-- wp:uagb/container {\"block_id\":\"a4b8e402\",\"innerContentCustomWidthDesktop\":1200,\"backgroundSizeTablet\":\"cover\",\"backgroundSizeMobile\":\"cover\",\"backgroundColor\":\"\",\"topPaddingDesktop\":100,\"bottomPaddingDesktop\":60,\"topPaddingTablet\":80,\"bottomPaddingTablet\":80,\"leftPaddingTablet\":30,\"rightPaddingTablet\":30,\"topPaddingMobile\":80,\"bottomPaddingMobile\":80,\"leftPaddingMobile\":30,\"rightPaddingMobile\":30,\"paddingLink\":false,\"variationSelected\":true,\"rowGapTablet\":0,\"isBlockRootParent\":true} -->\n<div class=\"wp-block-uagb-container uagb-block-a4b8e402 align