eritFromTheme\":true,\"classMigrate\":true,\"headingAlign\":\"left\",\"headingColor\":\"\",\"subHeadingColor\":\"\",\"headingTag\":\"h2\",\"subHeadFontSize\":18,\"headSpace\":20,\"subHeadSpace\":66,\"block_id\":\"cc48bcab\",\"ctaIcon\":\"arrow-right\",\"ctaIconSpace\":20,\"ctaType\":\"button\",\"ctaText\":\"Know More About Us\",\"ctaLink\":\"https://forthouse-reserve.com/about/\",\"ctaBtnLinkColor\":\"var(\\u002d\\u002dast-global-color-5)\",\"ctaLinkHoverColor\":\"var(\\u002d\\u002dast-global-color-5)\",\"ctaBgColor\":\"var(\\u002d\\u002dast-global-color-0)\",\"ctaBgHoverColor\":\"var(\\u002d\\u002dast-global-color-8)\",\"ctaBorderColor\":\"\",\"ctaBorderStyle\":\"\",\"showIcon\":false,\"btnBorderTopWidth\":1,\"btnBorderLeftWidth\":1,\"btnBorderRightWidth\":1,\"btnBorderBottomWidth\":1,\"btnBorderTopLeftRadius\":3,\"btnBorderTopRightRadius\":3,\"btnBorderBottomLeftRadius\":3,\"btnBorderBottomRightRadius\":3,\"btnBorderStyle\":\"none\",\"btnBorderColor\":\"#333\"} -->\n<div class=\"wp-block-uagb-info-box uagb-block-cc48bcab uagb-infobox__content-wrap  uagb-infobox-icon-above-title uagb-infobox-image-valign-top\"><div class=\"uagb-ifb-content\"><div class=\"uagb-ifb-title-wrap\"><h2 class=\"uagb-ifb-title\">Masters of Maritime Ingenuity: The Forthouse Identity</h2></div><p class=\"uagb-ifb-desc\">We are a marine logistics company that provides services to the upstream sector of the oil and gas industry. With a dynamic team, we are focused on delivering innovative and cost-effective solutions to our clients\' shipping and logistics challenges.<br><br>Our fleet of vessels, operated by an experienced crew, is designed to meet the unique demands of the upstream and downstream sectors of the oil and gas industry. We specialize in the shipping of crude oil, refined products and natural gas to and from key energy hubs worldwide, as well as the installation and maintenance of green energy systems, all of which are tailored to meet our clients\' specific needs.<br><br>Our team of experts works closely with clients to understand their unique requirements and develop customized solutions that optimize their supply chains, reduce costs and improve operational efficiency.</p><div class=\"uagb-ifb-button-wrapper wp-block-button\"><a href=\"https://forthouse-reserve.com/about/\" class=\"uagb-infobox-cta-link wp-block-button__link\" target=\"_self\" rel=\"noopener noreferrer\" onclick=\"return true;\" alt=\"\"><span class=\"uagb-inline-editing\">Know More About Us</span><svg xmlns=\"https://www.w3.org/2000/svg\" viewBox=\"0 0 448 512\"><path d=\"M438.6 278.6l-160 160C272.4 444.9 264.2 448 256 448s-16.38-3.125-22.62-9.375c-12.5-12.5-12.5-32.75 0-45.25L338.8 288H32C14.33 288 .0016 273.7 .0016 256S14.33 224 32 224h306.8l-105.4-105.4c-12.5-12.5-12.5-32.75 0-45.25s32.75-12.5 45.25 0l160 160C451.1 245.9 451.1 266.1 438.6 278.6z\"></path></svg></a></div></div></div>\n<!-- /wp:uagb/info-box --></div>\n<!-- /wp:uagb/container --></div></div>\n<!-- /wp:uagb/container -->\n\n<!-- wp:uagb/container {\"block_id\":\"aee62949\",\"innerContentCustomWidthDesktop\":1240,\"topPaddingDesktop\":100,\"bottomPaddingDesktop\":100,\"topPaddingTablet\":80,\"bottomPaddingTablet\":80,\"leftPaddingTablet\":20,\"rightPaddingTablet\":20,\"topPaddingMobile\":80,\"bottomPaddingMobile\":80,\"leftPaddingMobile\":20,\"rightPaddingMobile\":20,\"paddingLink\":false,\"variationSelected\":true,\"isBlockRootParent\":true} -->\n<div class=\"wp-block-uagb-container uagb-block-aee62949 alignfull uagb-is-root-container\"><div class=\"uagb-container-inner-blocks-wrap\"><!-- wp:uagb/advanced-heading {\"block_id\":\"5d255cf4\",\"classMigrate\":true,\"headSpace\":0} -->\n<div class=\"wp-block-uagb-advanced-heading uagb-block-5d255cf4\"><h2 class=\"uagb-heading-text\">Explore Our Tailored Solutions</h2></div>\n<!-- /wp:uagb/advanced-heading -->\n\n<!-- wp:uagb/container {\"block_id\":\"32b54f47\",\"directionDesktop\":\"row\",\"alignItemsDesktop\":\"flex-start\",\"topMarginDesktop\":20,\"bottom