",\"page\":\"360\",\"redirect\":\"\"}},\"antispam\":\"1\",\"akismet\":\"1\",\"anti_spam\":{\"time_limit\":{\"duration\":\"3\"}},\"recaptcha\":\"1\",\"form_tags\":[]},\"meta\":{\"template\":\"contact\"}}','Contact Form','','inherit','closed','closed','','7-revision-v1','','','2024-01-18 17:29:05','2024-01-18 16:29:05','',7,'https://forthouse-reserve.com/?p=783',0,'revision','',0),(784,1,'2024-01-18 17:31:37','2024-01-18 16:31:37','<!-- wp:uagb/container {\"block_id\":\"ddbe5c65\",\"backgroundType\":\"color\",\"backgroundSizeTablet\":\"cover\",\"backgroundSizeMobile\":\"cover\",\"backgroundColor\":\"var(\\u002d\\u002dast-global-color-0)\",\"topPaddingDesktop\":220,\"bottomPaddingDesktop\":120,\"topPaddingTablet\":160,\"bottomPaddingTablet\":50,\"leftPaddingTablet\":30,\"rightPaddingTablet\":30,\"topPaddingMobile\":160,\"bottomPaddingMobile\":50,\"leftPaddingMobile\":30,\"rightPaddingMobile\":30,\"paddingLink\":false,\"variationSelected\":true,\"isBlockRootParent\":true} -->\n<div class=\"wp-block-uagb-container uagb-block-ddbe5c65 alignfull uagb-is-root-container\"><div class=\"uagb-container-inner-blocks-wrap\"><!-- wp:uagb/advanced-heading {\"block_id\":\"fa4e7c56\",\"classMigrate\":true,\"headingDescToggle\":true,\"headingAlignMobile\":\"center\",\"headingColor\":\"var(\\u002d\\u002dast-global-color-5)\",\"subHeadingColor\":\"var(\\u002d\\u002dast-global-color-4)\",\"headingTag\":\"h1\",\"headSpace\":20,\"blockTopPadding\":0,\"blockRightPadding\":50,\"blockLeftPadding\":0,\"blockBottomPadding\":0,\"blockTopPaddingTablet\":0,\"blockRightPaddingTablet\":250,\"blockLeftPaddingTablet\":0,\"blockBottomPaddingTablet\":0,\"blockTopPaddingMobile\":0,\"blockRightPaddingMobile\":0,\"blockLeftPaddingMobile\":0,\"blockBottomPaddingMobile\":0,\"blockPaddingUnit\":\"%\"} -->\n<div class=\"wp-block-uagb-advanced-heading uagb-block-fa4e7c56\"><h1 class=\"uagb-heading-text\">Privacy Policyâ€‹</h1><p class=\"uagb-desc-text\">This policy is subject to change without notice, and it was last updated on the 18th of January 2024. By using this site, you agree that you have read and understood the contents of this policy.</p></div>\n<!-- /wp:uagb/advanced-heading --></div></div>\n<!-- /wp:uagb/container -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Who we are</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Forthouse Reserve Alliance Ltd. or â€œusâ€ or â€œweâ€ are an oil and gas sector services company located in Nigeria.&nbsp; Our website address is: https://forthouse-reserve.com.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">What personal data we collect and why we collect it</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>We collect your name and contact details, solely for the purpose of reaching out to you with information regarding our products and services. We do not collect or store your payment or credit/debit card information. All payments are received through a third-party payment gateway.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\"><strong>Age of Majority</strong></h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>You are only permitted to use this site if you are at least the age of majority in your state or province of residence, or you are the age of majority in your state or province of residence and you have given us your consent to allow any of your minor dependents to use this site.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Forthouse-reserve.com does not knowingly solicit or collect personally identifiable information online from children under the age of 13. If you become aware of any personally identifiable information we have collected from children under 13, please visit the&nbsp;<a href=\"https://forthouse-reserve.com/privacy-tools/\">Privacy Tools Page</a>&nbsp;and request for removal.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Minors under 18 years of age may have the personal information that they provided through the site deleted by visiting the&nbsp;<a href=\"https://forthouse-reserve.com/privacy-tools/\">Privacy Tools Page</a>.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Comments</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>When visitors leave comments on the site we collect the data shown in the comments form, and also the visitorâ€™s IP address and browser user agent string to help spam detection.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>An anonymized string created from your email address (also called a hash) may be provided to the Gravatar service to see if you are using it. The Gravatar service privacy policy is available here: <a href=\"https://automattic.com/privacy/\" target=\"_blank\" rel=\"noreferrer noopener\">https://automattic.com/privacy/</a>. After approval of your comment, your profile picture is visible to the public in the context of your comment.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Media</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>If you upload images to the website, you should avoid uploading images with embedded location data (EXIF GPS) included. Visitors to the website can download and extract any location data from images on the website.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Contact forms</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Our contact forms collect information that will help us to tailor our services specifically to meet your needs.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Cookies</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>If you leave a comment on our site you may opt-in to saving your name, email address and website in cookies. These are for your convenience so that you do not have to fill in your details again when you leave another comment. These cookies will last for one year.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>If you visit our login page, we will set a temporary cookie to determine if your browser accepts cookies. This cookie contains no personal data and is discarded when you close your browser.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>When you log in, we will also set up several cookies to save your login information and your screen display choices. Login cookies last for two days, and screen options cookies last for a year. If you select \"Remember Me\", your login will persist for two weeks. If you log out of your account, the login cookies will be removed.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>If you edit or publish an article, an additional cookie will be saved in your browser. This cookie includes no personal data and simply indicates the post ID of the article you just edited. It expires after 1 day.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Embedded content from other websites</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Articles on this site may include embedded content (e.g. videos, images, articles, etc.). Embedded content from other websites behaves in the exact same way as if the visitor has visited the other website.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>These websites may collect data about you, use cookies, embed additional third-party tracking, and monitor your interaction with that embedded content, including tracking your interaction with the embedded content if you have an account and are logged in to that website.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Embedded content from other websites</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Articles on this site may include embedded content (e.g. videos, images, articles, etc.). Embedded content from other websites behaves in the exact same way as if the visitor has visited the other website.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>These websites may collect data about you, use cookies, embed additional third-party tracking, and monitor your interaction with that embedded content, including tracking your interaction with the embedded content if you have an account and are logged in to that website.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Who we share your data with</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>We value your privacy, and we do not share your personal data with third parties. If you request a password reset, your IP address will be included in the reset email.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">How long we retain your data</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>If you leave a comment, the comment and its metadata are retained indefinitely. This is so we can recognize and approve any follow-up comments automatically instead of holding them in a moderation queue.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>For users that register on our website (if any), we also store the personal information they provide in their user profiles. All users can see, edit, or delete their personal information at any time (except they cannot change their username). Website administrators can also see and edit that information. Please visit the&nbsp;<a href=\"https://forthouse-reserve.com/privacy-tools/\">Privacy Tools Page</a>&nbsp;to view your personal data.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">What rights you have over your data</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>If you have an account on this site, or have left comments, you can request to receive an exported file of the personal data we hold about you, including any data you have provided to us. You can also request that we erase any personal data we hold about you. This does not include any data we are obliged to keep for administrative, legal, or security purposes.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Where your data is sent</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Visitor comments may be checked through an automated spam detection service.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Your contact information</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Your contact details will be stored in our records and used for reaching out to you concerning our products and services. You may request to know what data has been stored about you, and ask for that data to be deleted permanently. Please visit the&nbsp;<a href=\"https://forthouse-reserve.com/privacy-tools/\">Privacy Tools Page</a>&nbsp;to view your personal data.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>By using the site, you agree to the collection and use of information in accordance with this Privacy Policy.</p>\n<!-- /wp:paragraph -->','Privacy Policy','','inherit','closed','closed','','768-revision-v1','','','2024-01-18 17:31:37','2024-01-18 16:31:37','',768,'https://forthouse-reserve.com/?p=784',0,'revision','',0),(787,1,'2024-01-21 17:04:07','0000-00-00 00:00:00','Thank you for reading this post, don\'t forget to subscribe!','Display a message after the 1st paragraph of posts','','draft','closed','closed','','','','','2024-01-21 17:04:07','0000-00-00 00:00:00','',0,'https://forthouse-reserve.com/?post_type=wpcode&p=787',0,'wpcode','',0),(788,1,'2024-01-21 17:04:07','0000-00-00 00:00:00','add_action(\'admin_init\', function () {\r\n    // Redirect any user trying to access comments page\r\n    global $pagenow;\r\n    \r\n    if ($pagenow === \'edit-comments.php\') {\r\n        wp_safe_redirect(admin_url());\r\n        exit;\r\n    }\r\n\r\n    // Remove comments metabox from dashboard\r\n    remove_meta_box(\'dashboard_recent_comments\', \'dashboard\', \'normal\');\r\n\r\n    // Disable support for comments and trackbacks in post types\r\n    foreach (get_post_types() as $post_type) {\r\n        if (post_type_supports($post_type, \'comments\')) {\r\n            remove_post_type_support($post_type, \'comments\');\r\n            remove_post_type_support($post_type, \'trackbacks\');\r\n        }\r\n    }\r\n});\r\n\r\n// Close comments on the front-end\r\nadd_filter(\'comments_open\', \'__return_false\', 20, 2);\r\nadd_filter(\'pings_open\', \'__return_false\', 20, 2);\r\n\r\n// Hide existing comments\r\nadd_filter(\'comments_array\', \'__return_empty_array\', 10, 2);\r\n\r\n// Remove comments page in menu\r\nadd_action(\'admin_menu\', function () {\r\n    remove_menu_page(\'edit-comments.php\');\r\n});\r\n\r\n// Remove comments links from admin bar\r\nadd_action(\'init\', function () {\r\n    if (is_admin_bar_showing()) {\r\n        remove_action(\'admin_bar_menu\', \'wp_admin_bar_comments_menu\', 60);\r\n    }\r\n});','Completely Disable Comments','','draft','closed','closed','','','','','2024-01-21 17:04:07','0000-00-00 00:00:00','',0,'https://forthouse-reserve.com/?post_type=wpcode&p=788',0,'wpcode','',0),(794,1,'2024-05-13 18:05:10','2024-05-13 17:05:10','','Forthouse Reserve Company Profile (Download)','','publish','closed','closed','','forthouse-reserve-company-profile-download','','','2024-05-30 19:42:14','2024-05-30 18:42:14','',0,'https://forthouse-reserve.com/?post_type=pretty-link&#038;p=794',0,'pretty-link','',0),(798,1,'2024-05-13 18:20:54','2024-05-13 17:20:54','<!-- wp:uagb/container {\"block_id\":\"30c64779\",\"minHeightDesktop\":100,\"alignItemsTablet\":\"center\",\"alignItemsMobile\":\"center\",\"backgroundType\":\"color\",\"backgroundSizeTablet\":\"cover\",\"backgroundSizeMobile\":\"cover\",\"backgroundColor\":\"var(\\u002d\\u002dast-global-color-0)\",\"topPaddingDesktop\":220,\"bottomPaddingDesktop\":120,\"topPaddingTablet\":160,\"bottomPaddingTab