rightMarginMobile\":0,\"marginLink\":false,\"variationSelected\":true,\"widthSetByUser\":true} -->\n<div class=\"wp-block-uagb-container uagb-block-dd17ee84\"></div>\n<!-- /wp:uagb/container -->\n\n<!-- wp:uagb/container {\"block_id\":\"959de5be\",\"widthDesktop\":50,\"backgroundType\":\"color\",\"backgroundSizeTablet\":\"cover\",\"backgroundSizeMobile\":\"cover\",\"backgroundColor\":\"var(\\u002d\\u002dast-global-color-0)\",\"topPaddingDesktop\":0,\"bottomPaddingDesktop\":0,\"leftPaddingDesktop\":80,\"rightPaddingDesktop\":80,\"topPaddingTablet\":35,\"bottomPaddingTablet\":35,\"leftPaddingTablet\":35,\"rightPaddingTablet\":35,\"topPaddingMobile\":35,\"bottomPaddingMobile\":35,\"leftPaddingMobile\":35,\"rightPaddingMobile\":35,\"variationSelected\":true,\"widthSetByUser\":true} -->\n<div class=\"wp-block-uagb-container uagb-block-959de5be\"><!-- wp:uagb/advanced-heading {\"block_id\":\"a679106e\",\"classMigrate\":true,\"headingDescToggle\":true,\"headingColor\":\"var(\\u002d\\u002dast-global-color-5)\",\"subHeadingColor\":\"var(\\u002d\\u002dast-global-color-4)\",\"headSpace\":20} -->\n<div class=\"wp-block-uagb-advanced-heading uagb-block-a679106e\"><h2 class=\"uagb-heading-text\">We Solve Complex Logistics Challengesâ€‹</h2><p class=\"uagb-desc-text\">Our fleet of vessels, operated by an experienced crew, is designed to meet the unique demands of the upstream and downstream sectors of the oil and gas industry. We specialize in the shipping of crude oil, refined products and natural gas to and from key energy hubs worldwide, as well as the installation and maintenance of green energy systems, all of which are tailored to meet our clients\' specific needs.<br><br>Committed to innovation and continuous improvement, we are constantly exploring new technologies and approaches to optimize our operations and to deliver greater value to our clients.<br><br>With a strong focus on customer service, flexibility, and reliability, Forthouse Reserve Alliance is poised to become a leading player in the oil and gas shipping and logistics industry. We are committed to building strong and long-lasting relationships with our clients and partners, and we look forward to working together to meet the challenges and opportunities of the dynamic and rapidly evolving energy industry.<br><br></p></div>\n<!-- /wp:uagb/advanced-heading --></div>\n<!-- /wp:uagb/container --></div></div>\n<!-- /wp:uagb/container -->\n\n<!-- wp:uagb/container {\"block_id\":\"395f69b9\",\"directionDesktop\":\"row\",\"alignItemsDesktop\":\"flex-start\",\"backgroundSizeTablet\":\"cover\",\"backgroundSizeMobile\":\"cover\",\"backgroundColor\":\"\",\"topPaddingDesktop\":100,\"bottomPaddingDesktop\":100,\"topPaddingTablet\":80,\"bottomPaddingTablet\":80,\"leftPaddingTablet\":30,\"rightPaddingTablet\":30,\"topPaddingMobile\":80,\"bottomPaddingMobile\":80,\"leftPaddingMobile\":30,\"rightPaddingMobile\":30,\"paddingLink\":false,\"variationSelected\":true,\"rowGapMobile\":50,\"columnGapDesktop\":0,\"isBlockRootParent\":true} -->\n<div class=\"wp-block-uagb-container uagb-block-395f69b9 alignfull uagb-is-root-container\"><div class=\"uagb-container-inner-blocks-wrap\"><!-- wp:uagb/container {\"block_id\":\"a9a22e77\",\"widthDesktop\":64,\"topPaddingDesktop\":0,\"rightPaddingDesktop\":50,\"rightPaddingTablet\":50,\"paddingLink\":false,\"variationSelected\":true,\"widthSetByUser\":true} -->\n<div class=\"wp-block-uagb-container uagb-block-a9a22e77\"><!-- wp:uagb/advanced-heading {\"block_id\":\"992e1d53\",\"classMigrate\":true,\"headingDescToggle\":true,\"subHeadingColor\":\"\",\"headingTag\":\"h3\",\"headSpace\":20} -->\n<div class=\"wp-block-uagb-advanced-heading uagb-block-992e1d53\"><h3 class=\"uagb-heading-text\">Our Vision</h3><p class=\"uagb-desc-text\">To serve humanity through sustainable energy.</p></div>\n<!-- /wp:uagb/advanced-heading --></div>\n<!-- /wp:uagb/container -->\n\n<!-- wp:uagb/container {\"block_id\":\"a7a2a674\",\"widthDesktop\":64,\"topPaddingDesktop\":0,\"ri