addingMobile\":30,\"paddingLink\":false,\"variationSelected\":true,\"isBlockRootParent\":true} -->\n<div class=\"wp-block-uagb-container uagb-block-30c64779 alignfull uagb-is-root-container\"><div class=\"uagb-container-inner-blocks-wrap\"><!-- wp:uagb/advanced-heading {\"block_id\":\"96e68093\",\"classMigrate\":true,\"headingDescToggle\":true,\"headingAlignMobile\":\"center\",\"headingColor\":\"var(\\u002d\\u002dast-global-color-5)\",\"subHeadingColor\":\"var(\\u002d\\u002dast-global-color-4)\",\"headingTag\":\"h1\",\"headSpace\":20,\"blockTopPadding\":0,\"blockRightPadding\":25,\"blockLeftPadding\":0,\"blockBottomPadding\":0,\"blockTopPaddingTablet\":0,\"blockRightPaddingTablet\":250,\"blockLeftPaddingTablet\":0,\"blockBottomPaddingTablet\":0,\"blockTopPaddingMobile\":0,\"blockRightPaddingMobile\":0,\"blockLeftPaddingMobile\":0,\"blockBottomPaddingMobile\":0,\"blockPaddingUnit\":\"%\"} -->\n<div class=\"wp-block-uagb-advanced-heading uagb-block-96e68093\"><h1 class=\"uagb-heading-text\">About Us</h1><p class=\"uagb-desc-text\">Forthouse Reserve Alliance Ltd is an emerging innovation driven service provider in the oil and gas sector in Nigeria.<br><br>Incorporated in 2019 as a limited liability company in Nigeria, the main business focus of Forthouse is to facilitate trading and provide marine logistics in the oil and gas industry. Our new areas of focus are offshore equipment and energy technology.<br><br>Forthouse has been strategically positioned to deliver a sustainable competitive advantage that will efficiently satisfy clients and business partners globally, having access to and partnerships with key players and government agencies in the petroleum and gas sector worldwide.<br><br>In fulfilling our vision, we shall further engage new partnerships and continually align with emerging changes and reforms in the sector for more efficient service.</p></div>\n<!-- /wp:uagb/advanced-heading --></div></div>\n<!-- /wp:uagb/container -->\n\n<!-- wp:uagb/container {\"block_id\":\"f4853f72\",\"directionDesktop\":\"row\",\"alignItemsDesktop\":\"stretch\",\"alignItemsTablet\":\"center\",\"backgroundType\":\"gradient\",\"backgroundSizeTablet\":\"cover\",\"backgroundSizeMobile\":\"cover\",\"backgroundColor\":\"\",\"gradientValue\":\"linear-gradient(90deg,rgb(243,247,255) 51%,rgb(15,87,251) 51%)\",\"topPaddingDesktop\":0,\"leftPaddingTablet\":30,\"paddingLink\":false,\"topMarginDesktop\":120,\"bottomMarginDesktop\":0,\"leftMarginDesktop\":0,\"rightMarginDesktop\":0,\"topMarginTablet\":80,\"bottomMarginTablet\":0,\"leftMarginTablet\":0,\"rightMarginTablet\":0,\"topMarginMobile\":80,\"bottomMarginMobile\":0,\"leftMarginMobile\":0,\"rightMarginMobile\":0,\"marginLink\":false,\"variationSelected\":true,\"rowGapMobile\":0,\"columnGapDesktop\":0,\"isBlockRootParent\":true,\"equalHeight\":true,\"gradientColor1\":\"#7fbbe3\",\"gradientColor2\":\"var(\\u002d\\u002dast-global-color-0)\",\"selectGradient\":\"advanced\"} -->\n<div class=\"wp-block-uagb-container uagb-block-f4853f72 alignfull uagb-is-root-container\"><div class=\"uagb-container-inner-blocks-wrap\"><!-- wp:uagb/container {\"block_id\":\"dd17ee84\",\"widthDesktop\":50,\"minHeightDesktop\":500,\"minHeightTablet\":300,\"backgroundType\":\"image\",\"backgroundImageDesktop\":{\"uploading\":false,\"date\":1701855321000,\"filename\":\"green-energy-solar-panel-plant-forthouse-reserve-alliance-ltd.jpg\",\"menuOrder\":0,\"uploadedTo\":360,\"type\":\"image\",\"subtype\":\"jpeg\",\"id\":616,\"title\":\"green energy solar panel plant - forthouse reserve alliance ltd\",\"url\":\"https://forthouse-reserve.com/wp-content/uploads/2023/12/green-energy-solar-panel-plant-forthouse-reserve-alliance-ltd.jpg\",\"link\":\"https://forthouse-reserve.com/index.php/about/green-energy-solar-panel-plant-forthouse-reserve-alliance-ltd/\",\"alt\":\"green energy solar panel plant - forthouse reserve alliance ltd\",\"author\":\"1\",\"description\":\"\",\"caption\":\"\",\"name\":\"green-energy-solar-panel-plant-forthouse-reserve-alliance-ltd\",\"status\":\"inherit\",\"modified\":1701855321000,\"mime\":\"image/jpeg\",\"icon\":\"https://forthouse-reserve.com/wp-includes/images/media/default.png\",\"dateFormatted\":\"December 6, 2023\",\"nonces\":{\"update\":\"4ea7a81ce0\",\"delete\":\"4abfc08210\",\"edit\":\"b27fcae2a8\"},\"editLink\":\"https://forthouse-reserve.com/wp-admin/post.php?post=616\\u0026action=edit\",\"meta\":false,\"authorName\":\"Sn0wFlak3\",\"authorLink\":\"https://forthouse-reserve.com/wp-admin/profile.php\",\"uploadedToTitle\":\"About\",\"uploadedToLink\":\"https://forthouse-reserve.com/wp-admin/post.php?post=360\\u0026action=edit\",\"filesizeInBytes\":129624,\"filesizeHumanReadable\":\"127 KB\",\"context\":\"\",\"height\":810,\"width\":1215,\"orientation\":\"landscape\",\"sizes\":{\"thumbnail\":{\"height\":150,\"width\":150,\"url\":\"https://forthouse-reserve.com/wp-content/uploads/2023/12/green-energy-solar-panel-plant-forthouse-reserve-alliance-ltd-150x150.jpg\",\"orientation\":\"landscape\"},\"medium\":{\"height\":200,\"width\":300,\"url\":\"https://forthouse-reserve.com/wp-content/uploads/2023/12/green-energy-solar-panel-plant-forthouse-reserve-alliance-ltd-300x200.jpg\",\"orientation\":\"landscape\"},\"large\":{\"height\":683,\"width\":1024,\"url\":\"https://forthouse-reserve.com/wp-content/uploads/2023/12/green-energy-solar-panel-plant-forthouse-reserve-alliance-ltd-1024x683.jpg\",\"orientation\":\"landscape\"},\"full\":{\"url\":\"https://forthouse-reserve.com/wp-content/uploads/2023/12/green-energy-solar-panel-plant-forthouse-reserve-alliance-ltd.jpg\",\"height\":810,\"width\":1215,\"orientation\":\"landscape\"}},\"compat\":{\"item\":\"\",\"meta\":\"\"}},\"topMarginDesktop\":0,\"bottomMarginDesktop\":0,\"leftMarginDesktop\":0,\"rightMarginDesktop\":40,\"topMarginMobile\":0,\"bottomMarginMobile\":0,\"leftMarginMobile\":0,\"rightMarginMobile\":0,\"marginLink\":false,\"variationSelected\":true,\"widthSetByUser\":true} -->\n<div class=\"wp-block-uagb-container uagb-block-dd17ee84\"></div>\n<!-- /wp:uagb/container -->\n\n<!-- wp:uagb/container {\"block_id\":\"959de5be\",\"widthDesktop\":50,\"backgroundType\":\"color\",\"backgroundSizeTablet\":\"cover\",\"backgroundSizeMobile\":\"cover\",\"backgroundColor\":\"var(\\u002d\\u002dast-global-color-0)\",\"topPaddingDesktop\":0,\"bottomPaddingDesktop\":0,\"leftPaddingDesktop\":80,\"rightPaddingDesktop\":80,\"topPaddingTablet\":35,\"bottomPaddingTablet\":35,\"leftPaddingTablet\":35,\"rightPaddingTablet\":35,\"topPaddingMobile\":35,\"bottomPaddingMobile\":35,\"leftPaddingMobile\":35,\"rightPaddingMobile\":35,\"variationSelected\":true,\"widthSetByUser\":true} -->\n<div class=\"wp-block-uagb-container uagb-block-959de5be\"><!-- wp:uagb/advanced-heading {\"block_id\":\"a679106e\",\"classMigrate\":true,\"headingDescToggle\":true,\"headingColor\":\"var(\\u002d\\u002dast-global-color-5)\",\"subHeadingColor\":\"var(\\u002d\\u002dast-global-color-4)\",\"headSpace\":20} -->\n<div class=\"wp-block-uagb-advanced-heading uagb-block-a679106e\"><h2 class=\"uagb-heading-text\">We Solve Complex Logistics Challengesâ€‹</h2><p class=\"uagb-desc-text\">Our fleet of vessels, operated by an experienced crew, is designed to meet the unique demands of the upstream and downstream sectors of the oil and gas industry. We specialize in the shipping of crude oil, refined products and natural gas to and from key energy hubs worldwide, as well as the installation and maintenance of green energy systems, all of which are tailored to meet our clients\' specific needs.<br><br>Committed to innovation and continuous improvement, we are constantly exploring new technologies and approaches to optimize our operations and to deliver greater value to our clients.<br><br>With a strong focus on customer service, flexibility, and reliability, Forthouse Reserve Alliance is poised to become a leading player in the oil and gas shipping and logistics industry. We are committed to building strong and long-lasting relationships with our clients and partners, and we look forward to working together to meet the challenges and opportunities of the dynamic and rapidly evolving energy industry.<br><br></p></div>\n<!-- /wp:uagb/advanced-heading --></div>\n<!-- /wp:uagb/container --></div></div>\n<!-- /wp:uagb/container -->\n\n<!-- wp:uagb/container {\"block_id\":\"395f69b9\",\"directionDesktop\":\"row\",\"alignItemsDesktop\":\"flex-start\",\"backgroundSizeTablet\":\"cover\",\"backgroundSizeMobile\":\"cover\",\"backgroundColor\":\"\",\"topPaddingDesktop\":100,\"bottomPaddingDesktop\":100,\"topPaddingTablet\":80,\"bottomPaddingTablet\":80,\"leftPaddingTablet\":30,\"rightPaddingTablet\":30,\"topPaddingMobile\":80,\"bottomPaddingMobile\":80,\"leftPaddingMobile\":30,\"rightPaddingMobile\":30,\"paddingLink\":false,\"variationSelected\":true,\"rowGapMobile\":50,\"columnGapDesktop\":0,\"isBlockRootParent\":true} -->\n<div class=\"wp-block-uagb-container uagb-block-395f69b9 alignfull uagb-is-root-container\"><div class=\"uagb-container-inner-blocks-wrap\"><!-- wp:uagb/container {\"block_id\":\"a9a22e77\",\"widthDesktop\":64,\"topPaddingDesktop\":0,\"rightPaddingDesktop\":50,\"rightPaddingTablet\":50,\"paddingLink\":false,\"variationSelected\":true,\"widthSetByUser\":true} -->\n<div class=\"wp-block-uagb-container uagb-block-a9a22e77\"><!-- wp:uagb/advanced-heading {\"block_id\":\"992e1d53\",\"classMigrate\":true,\"headingDescToggle\":true,\"subHeadingColor\":\"\",\"headingTag\":\"h3\",\"headSpace\":20} -->\n<div class=\"wp-block-uagb-advanced-heading uagb-block-992e1d53\"><h3 class=\"uagb-heading-text\">Our Vision</h3><p class=\"uagb-desc-text\">To serve humanity through sustainable energy.</p></div>\n<!-- /wp:uagb/advanced-heading --></div>\n<!-- /wp:uagb/container -->\n\n<!-- wp:uagb/container {\"block_id\":\"a7a2a674\",\"widthDesktop\":64,\"topPaddingDesktop\":0,\"rightPaddingDesktop\":50,\"rightPaddingTablet\":50,\"paddingLink\":false,\"variationSelected\":true,\"widthSetByUser\":true} -->\n<div cla