list\\/\",\"order\":0}],\"order\":17},{\"title\":\"Login Security Plugin\",\"permalink\":\"https:\\/\\/www.wordfence.com\\/help\\/login-security-plugin\\/\",\"excerpt\":\"The Wordfence Login Security plugin contains a subset of the features found in the full Wordfence plugin: Two-factor Authentication, XML-RPC Protection and Login Page CAPTCHA. It is ideal for sites that need login security functionality but either canâ€™t or donâ€™t want to run the full Wordfence plugin.\",\"order\":18},{\"title\":\"Wordfence Intelligence\",\"permalink\":\"https:\\/\\/www.wordfence.com\\/help\\/wordfence-intelligence\\/\",\"excerpt\":\"Wordfence Intelligence is an industry-leading WordPress vulnerability database and evolving Threat Intelligence platform that contains over 12,000 records for vulnerabilities in WordPress plugins, themes, and core.\",\"children\":[{\"title\":\"V2: Accessing and Consuming the Vulnerability Data Feed\",\"permalink\":\"https:\\/\\/www.wordfence.com\\/help\\/wordfence-intelligence\\/v2-accessing-and-consuming-the-vulnerability-data-feed\\/\",\"order\":0},{\"title\":\"V1: Accessing and Consuming the Vulnerability Data Feed\",\"permalink\":\"https:\\/\\/www.wordfence.com\\/help\\/wordfence-intelligence\\/accessing-and-consuming-the-vulnerability-data-feed\\/\",\"order\":1},{\"title\":\"Wordfence Intelligence Webhook Notifications\",\"permalink\":\"https:\\/\\/www.wordfence.com\\/help\\/wordfence-intelligence\\/wordfence-intelligence-webhook-notifications\\/\",\"order\":2}],\"order\":19}]}','no'),('supportHash',_binary '9bcd7876de6fdd69ab54e0da0fc4d2d5a1d728b7cdfa7b7efd5cf99a73a6a6a2','yes'),('suspiciousAdminUsernames',_binary 'a:2:{i:0;s:46:\"/^wp\\.service\\.controller(?:\\.[a-zA-Z0-9]+)$/i\";i:1;s:55:\"/^(?:wordpressssadmin|wordprestadmin|jaime.besser56)$/i\";}','yes'),('timeoffset_wf',_binary '0','yes'),('timeoffset_wf_updated',_binary '1733740973','yes'),('tldlist',_binary '|com|org|net|edu|aaa|abb|abc|aco|ads|aeg|afl|aig|anz|aol|app|art|aws|axa|bar|bb